  // house-calculator-calculation-controller
  const houseCalculatorCalculationController = {
    scheduleCalculate(ui, container) {
      const {CONFIG} = HouseCalculatorUI.ctx;
      clearTimeout(ui.autoCalculateTimer);
      ui.autoCalculateTimer = setTimeout(() => {
        ui.autoCalculateTimer = null;
        ui.calculateSelectedRooms(container);
      }, CONFIG.AUTO_CALC_DELAY);
    },

    clearPendingCalculate(ui) {
      if (!ui.autoCalculateTimer) return;
      clearTimeout(ui.autoCalculateTimer);
      ui.autoCalculateTimer = null;
    },

    flushScheduledCalculate(ui, container) {
      if (!ui.autoCalculateTimer) return;
      ui.clearPendingCalculate();
      ui.calculateSelectedRooms(container);
    },

    calculateSelectedRooms(ui, container) {
      const {i18n} = HouseCalculatorUI.ctx;
      const selectedRooms = Array.from(
        container.querySelectorAll('#mst-hccp-rooms-container input[type="checkbox"]:checked')
      ).map((cb) => {
        const hrid = cb.value;
        return {
          hrid,
          fromLevel: parseInt(
            container.querySelector('.mst-hccp-level-input[data-room="' + hrid + '"][data-type="from"]').value,
            10
          ),
          toLevel: parseInt(
            container.querySelector('.mst-hccp-level-input[data-room="' + hrid + '"][data-type="to"]').value,
            10
          )
        };
      });

      if (selectedRooms.length === 0) {
        container.querySelector('#mst-hccp-results-text').value = i18n.t('selectHouseFirst');
        ui.lastResult = null;
        return;
      }

      try {
        const allMaterials = {};
        const roomDetails = [];
        selectedRooms.forEach(({hrid, fromLevel, toLevel}) => {
          try {
            const materials = ui.calculator.calculateUpgradeMaterials(hrid, fromLevel, toLevel);
            Object.entries(materials).forEach(
              ([
                itemHrid, count
              ]) => {
                allMaterials[itemHrid] = (allMaterials[itemHrid] || 0) + count;
              }
            );
            roomDetails.push({hrid, fromLevel, toLevel});
          } catch (error) {
            roomDetails.push({hrid, error: error.message});
          }
        });

        ui.lastResult = {materials: allMaterials, roomDetails};
        ui.displayResults(container, allMaterials, roomDetails);
      } catch (error) {
        container.querySelector('#mst-hccp-results-text').value = i18n.t('error') + ': ' + error.message;
        ui.lastResult = null;
      }
    },

    refreshResultDisplay(ui, container) {
      ui.clearPendingCalculate();
      ui.calculateSelectedRooms(container);
    }
  };

  // house-calculator-csv-export
  const houseCalculatorCsvExport = {
    exportCsv(ui, container) {
      const {i18n, utils} = HouseCalculatorUI.ctx;
      if (!ui.lastResult) {
        container.querySelector('#mst-hccp-results-text').value = i18n.t('noResultToExport');
        return;
      }

      const houseInfo = ui.lastResult.roomDetails
        .map((detail) => {
          if (detail.error) {
            return utils.getHouseName(detail.hrid) + ' (' + i18n.t('error') + ': ' + detail.error + ')';
          }
          return utils.getHouseName(detail.hrid) + ' (' + detail.fromLevel + '->' + detail.toLevel + ')';
        })
        .join(i18n.t('listSeparator'));
      const rows = [
        [
          i18n.t('csvUpgradeHouses'), houseInfo
        ], [], [
          i18n.t('csvMarketTime'), ui.marketDataService.getUpdatedText()
        ]
      ];

      const materialEntries = this.getMaterialEntries(ui, ui.lastResult.materials);
      const summary = this.getMaterialSummary(materialEntries);
      const materialRows = materialEntries.map((entry) => {
        return [
          entry.itemHrid, utils.getItemName(entry.itemHrid), this.formatMaterialCount(entry.itemHrid, entry.count), this.formatMaterialCount(entry.itemHrid, entry.available), this.formatMaterialCount(entry.itemHrid, entry.missing),
          this.formatCompactNumber(
            entry.marketPrice
          ), this.formatCompactNumber(entry.totalValue), this.formatCompactNumber(entry.valueGap)
        ];
      });

      rows.push([
        i18n.t('csvMaterialKinds'), summary.materialKinds, i18n.t('csvMissingCount'), summary.missingCount
      ]);
      rows.push([
        i18n.t(
          'csvTotalValue'
        ), this.formatCompactNumber(summary.totalValue), i18n.t('csvRequiredCoins'), this.formatCompactNumber(summary.requiredCoins), i18n.t('csvMaterialValue'),
        this.formatCompactNumber(summary.materialValue), i18n.t('csvValueGap'), this.formatCompactNumber(summary.valueGap)
      ]);
      rows.push([]);
      rows.push([
        i18n.t(
          'csvHrid'
        ), i18n.t('csvName'), i18n.t('csvRequiredCount'), i18n.t('csvAvailableCount'), i18n.t('csvMissingCount'),
        i18n.t('csvMarketPrice'), i18n.t('csvTotalValue'), i18n.t('csvValueGap')
      ]);
      rows.push(...materialRows);

      const csv = '\ufeff' + rows.map((row) => row.map((cell) => this.escapeCsvCell(cell)).join(',')).join('\r\n');
      const blob = new Blob(
        [
          csv
        ],
        {type: 'text/csv;charset=utf-8;'}
      );
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = i18n.t('csvFilenamePrefix') + '_' + utils.formatLocalFileTime() + '.csv';
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    }
  };

  // house-calculator-event-controller
  const houseCalculatorEventController = {
    bindEvents(ui, container) {
      container.querySelectorAll('#mst-hccp-rooms-container input[type="checkbox"]').forEach((checkbox) => {
        checkbox.addEventListener('change', () => {
          ui.toggleRoomSelected(checkbox);
          ui.scheduleCalculate(container);
        });
        ui.toggleRoomSelected(checkbox);
      });
      ui.updateSelectAllState(container);

      container.querySelectorAll('.mst-hccp-level-input[data-type="from"]').forEach((select) => {
        select.addEventListener('change', () => {
          ui.refreshToLevelOptions(select);
          ui.scheduleCalculate(container);
        });
      });
      container.querySelectorAll('.mst-hccp-level-input[data-type="to"]').forEach((select) => {
        select.addEventListener('change', () => ui.scheduleCalculate(container));
      });

      container
        .querySelector('#mst-hccp-select-life')
        .addEventListener('change', () => ui.toggleAllRooms(container, 'life'));
      container
        .querySelector('#mst-hccp-select-combat')
        .addEventListener('change', () => ui.toggleAllRooms(container, 'combat'));

      const batchFromSelect = container.querySelector('#mst-hccp-batch-from-level');
      const batchToSelect = container.querySelector('#mst-hccp-batch-to-level');
      const applyBatchFrom = () => {
        ui.refreshBatchToLevelOptions(container);
        ui.applyBatchFromLevel(container);
      };
      const applyBatchTo = () => ui.applyBatchToLevel(container);
      batchFromSelect.addEventListener('change', applyBatchFrom);
      batchFromSelect.addEventListener('blur', applyBatchFrom);
      batchToSelect.addEventListener('change', applyBatchTo);
      batchToSelect.addEventListener('blur', applyBatchTo);

      container.querySelector('#mst-hccp-refresh-levels').addEventListener('click', () => {
        ui.refreshRoomLevels(container);
      });
      container.querySelectorAll('input[name="display-format"]').forEach((input) => {
        input.addEventListener('change', () => ui.refreshResultDisplay(container));
      });
      container.querySelector('#mst-hccp-export-csv').addEventListener('click', () => {
        ui.flushScheduledCalculate(container);
        ui.exportCsv(container);
      });
      ui.bindMarketMateButton(container);
    }
  };

  // house-calculator-market-controller
  const houseCalculatorMarketController = {
    bindMarketMateButton(ui, container) {
      const button = container.querySelector('#mst-hccp-add-to-cart');
      if (!button || button.dataset.mstBound) return;
      button.dataset.mstBound = '1';
      button.addEventListener('click', () => ui.addMissingMaterialsToCart(container));
    },

    ensureMarketMateButton(ui, container) {
      const {MarketMateBridge, i18n, utils} = HouseCalculatorUI.ctx;
      if (!container?.isConnected || !MarketMateBridge.isReady()) return;
      let button = container.querySelector('#mst-hccp-add-to-cart');
      if (!button) {
        const actions = container.querySelector('.mst-hccp-output-buttons');
        button = utils.ensureButton({
          host: actions,
          id: 'mst-hccp-add-to-cart',
          text: i18n.t('addMissingToCart'),
          title: i18n.t('addMissingToCartTitle')
        });
      }
      if (!button) return;
      ui.bindMarketMateButton(container);
    },

    addMissingMaterialsToCart(ui, container) {
      const {DataHub, MarketMateBridge, i18n} = HouseCalculatorUI.ctx;
      const {Notifier} = HouseCalculatorUI;
      if (!MarketMateBridge.isReady()) {
        container.querySelector('#mst-hccp-add-to-cart')?.remove();
        Notifier.toast(i18n.t('marketMateUnavailable'), 'warning');
        return;
      }
      ui.flushScheduledCalculate(container);
      if (!ui.lastResult) {
        Notifier.toast(i18n.t('noResultToExport'), 'warning');
        return;
      }
      const items = ui
        .getMaterialEntries(ui.lastResult.materials)
        .filter((entry) => entry.itemHrid !== '/items/coin' && entry.missing > 0)
        .map((entry) => ({
          itemId: entry.itemHrid,
          name: DataHub.resolveItemName(entry.itemHrid),
          iconRef: entry.itemHrid,
          quantity: Math.ceil(entry.missing),
          source: 'mst_house'
        }));
      if (!items.length) {
        Notifier.toast(i18n.t('enoughMaterials'), 'info');
        return;
      }
      const response = MarketMateBridge.addToCart(items);
      if (!response?.ok || !response.added) {
        Notifier.toast(response?.error || i18n.t('abilityBooksCartFailed'), 'error');
        return;
      }
      const quantity = items.reduce((sum, item) => sum + item.quantity, 0);
      Notifier.toast(
        i18n.t('addMissingToCartDone', response.added || 0, quantity.toLocaleString(i18n.locale)),
        'success'
      );
    }
  };

  // house-calculator-material-summary
  const houseCalculatorMaterialSummary = {
    getMaterialEntries(ui, materials) {
      const {DataHub, CharacterDataService} = HouseCalculatorUI.ctx;
      const sortByIndex = (a, b) => {
        const indexA = DataHub.getItemDetail(a.itemHrid)?.sortIndex ?? 9999;
        const indexB = DataHub.getItemDetail(b.itemHrid)?.sortIndex ?? 9999;
        return indexA - indexB;
      };
      const entries = Object.entries(materials).map(
        ([
          itemHrid, count
        ]) => {
          const available = CharacterDataService.getInventoryCount(itemHrid);
          const missing = Math.max(0, count - available);
          const marketPrice = ui.marketDataService.getPrice(itemHrid);
          const totalValue = count * marketPrice;
          const valueGap = itemHrid === '/items/coin' ? 0 : missing * marketPrice;
          return {itemHrid, count, available, missing, marketPrice, totalValue, valueGap};
        }
      );
      const existingEntries = entries.filter((entry) => entry.missing === 0).sort(sortByIndex);
      const neededEntries = entries.filter((entry) => entry.missing > 0).sort(sortByIndex);
      return existingEntries.concat(neededEntries);
    },

    getMaterialSummary(materialEntries) {
      return materialEntries.reduce(
        (summary, entry) => {
          summary.materialKinds += 1;
          summary.totalValue += entry.totalValue;
          summary.valueGap += entry.valueGap;
          if (entry.itemHrid === '/items/coin') {
            summary.requiredCoins += entry.count;
          } else {
            summary.missingCount += entry.missing;
            summary.materialValue += entry.totalValue;
          }
          return summary;
        },
        {materialKinds: 0, missingCount: 0, totalValue: 0, valueGap: 0, requiredCoins: 0, materialValue: 0}
      );
    }
  };

  // house-calculator-result-display
  const houseCalculatorResultDisplay = {
    displayResults(ui, container, materials, roomDetails) {
      const {i18n, utils} = HouseCalculatorUI.ctx;
      const resultsText = container.querySelector('#mst-hccp-results-text');
      const useHrid = container.querySelector('input[name="display-format"]:checked').value === 'hrid';

      let output =
        i18n.t('upgradedHouses') +
        '\n' +
        roomDetails
          .map((detail) => {
            if (detail.error) {
              const name = useHrid ? detail.hrid : utils.getHouseName(detail.hrid);
              return '• ' + name + ' (' + i18n.t('error') + ': ' + detail.error + ')';
            }
            const name = useHrid ? detail.hrid : utils.getHouseName(detail.hrid);
            return '• ' + name + ' (' + detail.fromLevel + '->' + detail.toLevel + ')';
          })
          .join('\n') +
        '\n\n';

      const materialEntries = this.getMaterialEntries(ui, materials);
      const summary = this.getMaterialSummary(materialEntries);
      const existingEntries = materialEntries.filter((entry) => entry.missing === 0);
      const neededEntries = materialEntries.filter((entry) => entry.missing > 0);

      output += i18n.t('summaryInfo') + '\n';
      output += '• ' + i18n.t('marketDataTime') + ': ' + ui.marketDataService.getUpdatedText() + '\n';
      output += '• ' + i18n.t('csvMaterialKinds') + ': ' + summary.materialKinds.toLocaleString(i18n.locale) + '\n';
      output += '• ' + i18n.t('csvMissingCount') + ': ' + summary.missingCount.toLocaleString(i18n.locale) + '\n';
      output += '• ' + i18n.t('csvTotalValue') + ': ' + this.formatCompactNumber(summary.totalValue) + '\n';
      output += '• ' + i18n.t('csvRequiredCoins') + ': ' + this.formatCompactNumber(summary.requiredCoins) + '\n';
      output += '• ' + i18n.t('csvMaterialValue') + ': ' + this.formatCompactNumber(summary.materialValue) + '\n';
      output += '• ' + i18n.t('csvValueGap') + ': ' + this.formatCompactNumber(summary.valueGap) + '\n\n';
      output += i18n.t('existingMaterials') + '\n';

      if (existingEntries.length === 0) {
        output += '• ' + i18n.t('noExistingMaterials') + '\n\n';
      } else {
        existingEntries.forEach((entry) => {
          output += this.formatMaterialResultLine(entry, useHrid) + '\n';
        });
        output += '\n';
      }

      output += i18n.t('requiredMaterials') + '\n';

      if (neededEntries.length === 0) {
        output += '• ' + i18n.t('enoughMaterials');
      } else {
        neededEntries.forEach((entry) => {
          output += this.formatMaterialResultLine(entry, useHrid) + '\n';
        });
      }

      resultsText.value = output;
    }
  };

  // house-calculator-result-formatters
  const houseCalculatorResultFormatters = {
    escapeCsvCell(value) {
      const text = String(value ?? '');
      return /[",\r\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
    },

    formatCompactNumber(value) {
      const number = Number(value) || 0;
      const abs = Math.abs(number);
      const units = [
        {value: 1e12, suffix: 'T'}, {value: 1e9, suffix: 'B'}, {value: 1e6, suffix: 'M'}, {value: 1e3, suffix: 'K'}
      ];
      const unit = units.find((item) => abs >= item.value);
      if (!unit) return number.toFixed(2).replace(/\.?0+$/, '');
      return (number / unit.value).toFixed(2).replace(/\.?0+$/, '') + unit.suffix;
    },

    formatMaterialCount(itemHrid, value) {
      const {i18n} = HouseCalculatorUI.ctx;
      return itemHrid === '/items/coin' ? this.formatCompactNumber(value) : value.toLocaleString(i18n.locale);
    },

    formatMaterialResultLine(entry, useHrid) {
      const {i18n, utils} = HouseCalculatorUI.ctx;
      const costDisplay =
        entry.valueGap > 0
          ? ' (' + i18n.t('value') + ': ' + this.formatCompactNumber(entry.valueGap) + ' ' + i18n.t('coins') + ')'
          : '';
      const displayName = useHrid ? entry.itemHrid : utils.getItemName(entry.itemHrid);
      return (
        '• ' +
        displayName +
        ': ' +
        i18n.t('need') +
        ' ' +
        this.formatMaterialCount(entry.itemHrid, entry.missing) +
        ' (' +
        i18n.t('now') +
        ' ' +
        this.formatMaterialCount(entry.itemHrid, entry.available) +
        '/' +
        this.formatMaterialCount(entry.itemHrid, entry.count) +
        ')' +
        costDisplay
      );
    }
  };

  // house-calculator-results
  const houseCalculatorResults = {
    ...houseCalculatorResultFormatters,
    ...houseCalculatorMaterialSummary,
    ...houseCalculatorCsvExport,
    ...houseCalculatorResultDisplay
  };

  // house-calculator-room-controller
  const houseCalculatorRoomController = {
    toggleRoomSelected(ui, checkbox) {
      const roomDiv = checkbox.closest('.mst-hccp-room-checkbox');
      roomDiv.classList.toggle('mst-hccp-room-selected', checkbox.checked);
      ui.updateSelectAllState(checkbox.closest('#mst-hccp-house-calculator'));
    },

    updateSelectAllState(container) {
      if (!container) return;
      [
        'life', 'combat'
      ].forEach((group) => {
        const selectAll = container.querySelector('#mst-hccp-select-' + group);
        const checkboxes = Array.from(
          container.querySelectorAll('#mst-hccp-rooms-container input[type="checkbox"][data-group="' + group + '"]')
        );
        if (!selectAll || checkboxes.length === 0) return;
        const checkedCount = checkboxes.filter((cb) => cb.checked).length;
        selectAll.checked = checkedCount === checkboxes.length;
        selectAll.indeterminate = checkedCount > 0 && checkedCount < checkboxes.length;
      });
    },

    refreshToLevelOptions(fromSelect) {
      const {CONFIG, TemplateRenderer, utils} = HouseCalculatorUI.ctx;
      const hrid = fromSelect.getAttribute('data-room');
      const fromLevel = utils.clampLevel(fromSelect.value, CONFIG.MIN_FROM_LEVEL, CONFIG.MAX_FROM_LEVEL);
      const toSelect = document.querySelector('.mst-hccp-level-input[data-room="' + hrid + '"][data-type="to"]');
      const selected = Math.max(fromLevel + 1, parseInt(toSelect.value, 10) || fromLevel + 1);
      TemplateRenderer.renderHtml(
        () => utils.createLevelOptions(fromLevel + 1, CONFIG.MAX_TO_LEVEL, Math.min(CONFIG.MAX_TO_LEVEL, selected)),
        toSelect
      );
    },

    refreshBatchToLevelOptions(container) {
      const {CONFIG, TemplateRenderer, utils} = HouseCalculatorUI.ctx;
      const fromSelect = container.querySelector('#mst-hccp-batch-from-level');
      const toSelect = container.querySelector('#mst-hccp-batch-to-level');
      const fromLevel = utils.clampLevel(fromSelect.value, CONFIG.MIN_FROM_LEVEL, CONFIG.MAX_FROM_LEVEL);
      const selected = Math.max(fromLevel + 1, parseInt(toSelect.value, 10) || fromLevel + 1);
      TemplateRenderer.renderHtml(
        () => utils.createLevelOptions(fromLevel + 1, CONFIG.MAX_TO_LEVEL, Math.min(CONFIG.MAX_TO_LEVEL, selected)),
        toSelect
      );
    },

    toggleAllRooms(ui, container, group) {
      const selectAll = container.querySelector('#mst-hccp-select-' + group);
      const checkboxes = Array.from(
        container.querySelectorAll('#mst-hccp-rooms-container input[type="checkbox"][data-group="' + group + '"]')
      );
      const targetChecked = selectAll.checked;
      checkboxes.forEach((cb) => {
        cb.checked = targetChecked;
        ui.toggleRoomSelected(cb);
      });
      ui.updateSelectAllState(container);
      ui.scheduleCalculate(container);
    },

    refreshRoomLevels(ui, container) {
      const {TemplateRenderer} = HouseCalculatorUI.ctx;
      const checkedHrids = new Set(
        Array.from(container.querySelectorAll('#mst-hccp-rooms-container input[type="checkbox"]:checked')).map(
          (cb) => cb.value
        )
      );
      const roomState = ui.getRoomLevelsFromUI();
      ui.currentRoomLevels = roomState.roomLevels;
      ui.roomIcons = roomState.roomIcons;

      const roomsContainer = container.querySelector('#mst-hccp-rooms-container');
      TemplateRenderer.renderHtml(() => ui.renderRooms(), roomsContainer);
      roomsContainer.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
        checkbox.checked = checkedHrids.has(checkbox.value);
        checkbox.addEventListener('change', () => {
          ui.toggleRoomSelected(checkbox);
          ui.scheduleCalculate(container);
        });
        ui.toggleRoomSelected(checkbox);
      });
      roomsContainer.querySelectorAll('.mst-hccp-level-input[data-type="from"]').forEach((select) => {
        select.addEventListener('change', () => {
          ui.refreshToLevelOptions(select);
          ui.scheduleCalculate(container);
        });
      });
      roomsContainer.querySelectorAll('.mst-hccp-level-input[data-type="to"]').forEach((select) => {
        select.addEventListener('change', () => ui.scheduleCalculate(container));
      });
      ui.updateSelectAllState(container);
      ui.scheduleCalculate(container);
    },

    applyBatchFromLevel(ui, container) {
      const batchFromLevel = parseInt(container.querySelector('#mst-hccp-batch-from-level').value, 10);
      container.querySelectorAll('.mst-hccp-level-input[data-type="from"]').forEach((fromSelect) => {
        fromSelect.value = String(batchFromLevel);
        ui.refreshToLevelOptions(fromSelect);
      });
      ui.scheduleCalculate(container);
    },

    applyBatchToLevel(ui, container) {
      const {CONFIG, utils} = HouseCalculatorUI.ctx;
      const batchToLevel = utils.clampLevel(
        container.querySelector('#mst-hccp-batch-to-level').value,
        2,
        CONFIG.MAX_TO_LEVEL
      );
      container.querySelectorAll('.mst-hccp-level-input[data-type="to"]').forEach((toSelect) => {
        const hrid = toSelect.getAttribute('data-room');
        const fromSelect = container.querySelector('.mst-hccp-level-input[data-room="' + hrid + '"][data-type="from"]');
        const fromLevel = utils.clampLevel(fromSelect.value, CONFIG.MIN_FROM_LEVEL, CONFIG.MAX_FROM_LEVEL);
        toSelect.value = String(Math.max(batchToLevel, fromLevel + 1));
      });
      ui.scheduleCalculate(container);
    },

    getRoomLevelsFromUI(ui) {
      const {CONFIG, DataHub, CharacterDataService, utils} = HouseCalculatorUI.ctx;
      const roomLevels = {};
      const roomIcons = {...ui.roomIcons};
      const roomDivs = document.querySelectorAll('[class*="HousePanel_housePanel__"] [class*="HousePanel_houseRoom__"]');
      const houseSpriteUrl =
        utils.getSvgSpriteUrl('[class*="HousePanel_houseRoom__"] svg use') ||
        utils.getSpriteUrl('misc') ||
        '/static/media/misc_sprite.cfad291b.svg';
      const houseNameToHrid = new Map();

      Object.entries(ui.houseDetails).forEach(
        ([
          hrid, detail
        ]) => {
          const names = [
            detail?.name, detail?.nameZh, DataHub.clientData.indexes.houseHridToNameEn?.get(hrid), DataHub.clientData.indexes.houseHridToNameZh?.get(hrid)
          ];
          names.forEach((name) => {
            if (name) houseNameToHrid.set(String(name).trim(), hrid);
          });
        }
      );

      roomDivs.forEach((div) => {
        const nameElement = div.querySelector('[class*="HousePanel_name__"]');
        const levelElement = div.querySelector('[class*="HousePanel_level__"]');
        const iconElement = div.querySelector('svg use');
        if (!nameElement || !levelElement) return;

        const name = nameElement.textContent.trim();
        const levelMatch = levelElement.textContent.match(/\d+/);
        const level = levelMatch ? parseInt(levelMatch[0], 10) : CONFIG.MIN_FROM_LEVEL;
        const iconHref = utils.getSvgUseHref(iconElement);
        const iconFragment = iconHref?.split('#').pop() || '';
        // 遊戲房屋圖示固定使用 #house_<room-id>，直接還原 HRID 可避開語言和 CSS 雜湊變化。
        const iconHrid = iconFragment.startsWith('house_') ? '/house_rooms/' + iconFragment.slice('house_'.length) : null;
        const hrid = (iconHrid && ui.houseDetails[iconHrid] ? iconHrid : null) || houseNameToHrid.get(name);

        if (hrid) {
          roomLevels[hrid] = level;
          if (iconHref) roomIcons[hrid] = iconHref;
        }
      });

      // 與 PGE 的圖示解析方式一致：從當前頁面獲取帶即時 hash 的 sprite 路徑。
      {
        Object.keys(ui.houseDetails).forEach((hrid) => {
          if (!roomIcons[hrid]) {
            roomIcons[hrid] = houseSpriteUrl + '#house_' + utils.substrLastSlash(hrid);
          }
        });
      }

      const characterHouseRoomMap = CharacterDataService.raw?.characterHouseRoomMap || {};
      Object.entries(characterHouseRoomMap).forEach(
        ([
          hrid, data
        ]) => {
          if (!roomLevels[hrid] && ui.houseDetails[hrid]) {
            roomLevels[hrid] = utils.clampLevel(
              data?.level || CONFIG.MIN_FROM_LEVEL,
              CONFIG.MIN_FROM_LEVEL,
              CONFIG.MAX_FROM_LEVEL
            );
          }
        }
      );

      return {roomLevels, roomIcons};
    }
  };

  // house-calculator-view
  const houseCalculatorView = {
    render(ui) {
      const {CONFIG, MarketMateBridge, i18n, utils} = HouseCalculatorUI.ctx;
      return [
        '<div class="mst-hccp-calculator-body">', '<div class="mst-hccp-calculator-toolbar">', '  <div class="mst-hccp-select-groups">', '  <label class="mst-hccp-select-all-label"><input type="checkbox" id="mst-hccp-select-life"> ' + utils.escapeHtml(i18n.t('selectLife')) + '</label>', '  <label class="mst-hccp-select-all-label"><input type="checkbox" id="mst-hccp-select-combat"> ' + utils.escapeHtml(i18n.t('selectCombat')) + '</label>',
        '</div>', '  <div class="mst-hccp-toolbar-actions">', '  <div class="mst-hccp-batch-level">', '    <select id="mst-hccp-batch-from-level" class="mst-hccp-level-input mst-hccp-batch-level-input" title="' + utils.escapeHtml(i18n.t('batchStart')) + '">' + utils.createLevelOptions(CONFIG.MIN_FROM_LEVEL, CONFIG.MAX_FROM_LEVEL, CONFIG.MIN_FROM_LEVEL) + '</select>', '      <span class="mst-hccp-level-arrow">→</span>',
        '    <select id="mst-hccp-batch-to-level" class="mst-hccp-level-input mst-hccp-batch-level-input" title="' +
          utils.escapeHtml(i18n.t('batchTarget')) +
          '">' +
          utils.createLevelOptions(2, CONFIG.MAX_TO_LEVEL, CONFIG.MAX_TO_LEVEL) +
          '</select>', '</div>', '  <button id="mst-hccp-refresh-levels">' + utils.escapeHtml(i18n.t('refreshLevels')) + '</button>', '</div>', '</div>',
        '<div id="mst-hccp-rooms-container">' +
          this.renderRooms(ui) +
          '</div>', '<div class="mst-hccp-output-actions">', '  <div class="mst-hccp-display-option">', '  <span>' + utils.escapeHtml(i18n.t('itemDisplayFormat')) + '</span>', '  <label><input type="radio" name="display-format" value="name" checked> ' + utils.escapeHtml(i18n.t('name')) + '</label>',
        '  <label><input type="radio" name="display-format" value="hrid"> HRID</label>', '</div>', '  <div class="mst-hccp-output-buttons">', '    <button id="mst-hccp-export-csv">' + utils.escapeHtml(i18n.t('exportCsv')) + '</button>', MarketMateBridge.isReady() ? '    <button id="mst-hccp-add-to-cart" title="' + utils.escapeHtml(i18n.t('addMissingToCartTitle')) + '">' + utils.escapeHtml(i18n.t('addMissingToCart')) + '</button>' : '',
        '</div>', '</div>', '<textarea id="mst-hccp-results-text" readonly placeholder="' + utils.escapeHtml(i18n.t('resultPlaceholder')) + '"></textarea>', '</div>'
      ].join('');
    },

    renderRooms(ui) {
      const {CONFIG, i18n, utils} = HouseCalculatorUI.ctx;
      return Object.keys(ui.houseDetails)
        .sort((a, b) => {
          const sortA = ui.houseDetails[a]?.sortIndex ?? 9999;
          const sortB = ui.houseDetails[b]?.sortIndex ?? 9999;
          return sortA - sortB || a.localeCompare(b);
        })
        .map((hrid, index) => {
          const room = ui.houseDetails[hrid];
          if (!room) return '';
          const houseGroup = index < 10 ? 'life' : 'combat';
          const currentLevel = utils.clampLevel(
            ui.currentRoomLevels[hrid] || CONFIG.MIN_FROM_LEVEL,
            CONFIG.MIN_FROM_LEVEL,
            CONFIG.MAX_FROM_LEVEL
          );
          const toLevel = Math.min(CONFIG.MAX_TO_LEVEL, currentLevel + 1);
          const iconHref = ui.roomIcons[hrid] || '';
          const iconHtml = iconHref
            ? '<span class="mst-hccp-room-icon"><svg role="img" aria-label="' +
              utils.escapeHtml(i18n.t('roomIcon')) +
              '" width="1em" height="1em" class="Icon_icon__2LtL_ Icon_small__2bxvH"><use href="' +
              utils.escapeHtml(iconHref) +
              '"></use></svg></span>'
            : '';
          return [
            '<div class="mst-hccp-room-checkbox" data-hrid="' +
              utils.escapeHtml(hrid) +
              '">', '  <div class="mst-hccp-room-row">', '    <label class="mst-hccp-room-left">', '      <input type="checkbox" value="' + utils.escapeHtml(hrid) + '" data-group="' + houseGroup + '">', iconHtml,
            '      <span class="mst-hccp-room-name">' +
              utils.escapeHtml(utils.getHouseName(hrid)) +
              '</span>', '</label>', '    <div class="mst-hccp-room-levels">', '      <select class="mst-hccp-level-input" data-room="' + utils.escapeHtml(hrid) + '" data-type="from">' + utils.createLevelOptions(CONFIG.MIN_FROM_LEVEL, CONFIG.MAX_FROM_LEVEL, currentLevel) + '</select>', '      <span class="mst-hccp-level-arrow">→</span>',
            '      <select class="mst-hccp-level-input" data-room="' +
              utils.escapeHtml(hrid) +
              '" data-type="to">' +
              utils.createLevelOptions(currentLevel + 1, CONFIG.MAX_TO_LEVEL, toLevel) +
              '</select>', '</div>', '</div>', '</div>'
          ].join('');
        })
        .join('');
    }
  };

  // house-calculator-ui
  class HouseCalculatorUI {
    static ctx = null;
    static Notifier = null;
    static calculationController = null;
    static eventController = null;
    static marketController = null;
    static results = null;
    static roomController = null;
    static view = null;

    static configure(ctx, Notifier) {
      this.ctx = ctx;
      this.Notifier = Notifier;
      this.calculationController = houseCalculatorCalculationController;
      this.eventController = houseCalculatorEventController;
      this.marketController = houseCalculatorMarketController;
      this.results = houseCalculatorResults;
      this.roomController = houseCalculatorRoomController;
      this.view = houseCalculatorView;
    }

    constructor(houseDetailMap, calculator, marketDataService) {
      this.houseDetails = houseDetailMap;
      this.calculator = calculator;
      this.marketDataService = marketDataService;
      this.currentRoomLevels = {};
      this.roomIcons = {};
      this.lastResult = null;
      this.autoCalculateTimer = null;
      this.helpController = null;
    }

    create() {
      const {CalculatorHelpPopover, MarketMateBridge, TemplateRenderer, i18n} = this.constructor.ctx;
      const {Notifier} = this.constructor;
      this.clearPendingCalculate();
      this.lastResult = null;
      const old = document.getElementById('mst-hccp-house-calculator');
      if (old) {
        if (typeof Swal !== 'undefined' && Swal.getPopup?.()?.contains(old)) Swal.close();
        else old.remove();
      }

      const roomState = this.getRoomLevelsFromUI();
      this.currentRoomLevels = roomState.roomLevels;
      this.roomIcons = roomState.roomIcons;
      this.injectStyles();

      return Notifier.html({
        title: i18n.t('title'),
        html: () => TemplateRenderer.html`<div id="mst-hccp-house-calculator"></div>`,
        width: '27rem',
        popupClass: 'mst-house-calculator-dialog',
        icon: 'house',
        didOpen: (popup) => {
          const container = popup.querySelector('#mst-hccp-house-calculator');
          if (!container) return;
          TemplateRenderer.renderHtml(() => this.render(), container);
          this.bindEvents(container);
          this.helpController?.cleanup();
          this.helpController = CalculatorHelpPopover.mount({
            popup,
            moduleName: 'house',
            title: i18n.t('houseCalculatorHelpTitle'),
            heading: i18n.t('title'),
            content: i18n.t('houseCalculatorHelp')
          });
          MarketMateBridge.onReady(() => this.ensureMarketMateButton(container));
        },
        willClose: () => {
          this.helpController?.cleanup();
          this.helpController = null;
          this.clearPendingCalculate();
        }
      });
    }

    injectStyles() {
      StyleService.ensure('mst-hccp-style', MST_HOUSE_CALCULATOR_CSS);
    }

    render() {
      return this.constructor.view.render(this);
    }

    renderRooms() {
      return this.constructor.view.renderRooms(this);
    }

    bindEvents(container) {
      return this.constructor.eventController.bindEvents(this, container);
    }

    bindMarketMateButton(container) {
      return this.constructor.marketController.bindMarketMateButton(this, container);
    }

    ensureMarketMateButton(container) {
      return this.constructor.marketController.ensureMarketMateButton(this, container);
    }

    addMissingMaterialsToCart(container) {
      return this.constructor.marketController.addMissingMaterialsToCart(this, container);
    }

    rerenderForLanguage(container, nextLang) {
      const {CalculatorHelpPopover, TemplateRenderer, i18n} = this.constructor.ctx;
      if (nextLang !== 'zh' && nextLang !== 'en') return;
      if (!i18n.setLanguage(nextLang)) return;
      const checkedHrids = new Set(
        Array.from(container.querySelectorAll('#mst-hccp-rooms-container input[type="checkbox"]:checked')).map(
          (cb) => cb.value
        )
      );
      const roomLevels = {};
      container.querySelectorAll('.mst-hccp-level-input[data-type="from"]').forEach((fromSelect) => {
        const hrid = fromSelect.getAttribute('data-room');
        const toSelect = container.querySelector('.mst-hccp-level-input[data-room="' + hrid + '"][data-type="to"]');
        roomLevels[hrid] = {fromLevel: parseInt(fromSelect.value, 10), toLevel: parseInt(toSelect.value, 10)};
      });
      const displayFormat = container.querySelector('input[name="display-format"]:checked')?.value || 'name';

      TemplateRenderer.renderHtml(() => this.render(), container);
      this.bindEvents(container);
      const popup = container.closest('.swal2-popup');
      const swalTitle = popup?.querySelector('.swal2-title');
      if (swalTitle) swalTitle.textContent = i18n.t('title');
      if (popup) {
        this.helpController?.cleanup();
        this.helpController = CalculatorHelpPopover.mount({
          popup,
          moduleName: 'house',
          title: i18n.t('houseCalculatorHelpTitle'),
          heading: i18n.t('title'),
          content: i18n.t('houseCalculatorHelp')
        });
      }

      Object.entries(roomLevels).forEach(
        ([
          hrid, levels
        ]) => {
          const fromSelect = container.querySelector('.mst-hccp-level-input[data-room="' + hrid + '"][data-type="from"]');
          if (!fromSelect) return;
          fromSelect.value = String(levels.fromLevel);
          this.refreshToLevelOptions(fromSelect);
          const toSelect = container.querySelector('.mst-hccp-level-input[data-room="' + hrid + '"][data-type="to"]');
          if (toSelect) toSelect.value = String(levels.toLevel);
        }
      );
      container.querySelectorAll('#mst-hccp-rooms-container input[type="checkbox"]').forEach((checkbox) => {
        checkbox.checked = checkedHrids.has(checkbox.value);
        this.toggleRoomSelected(checkbox);
      });
      const displayInput = container.querySelector('input[name="display-format"][value="' + displayFormat + '"]');
      if (displayInput) displayInput.checked = true;
      const triggerBtn = document.getElementById('mst-hccp-house-calculator-trigger');
      if (triggerBtn) triggerBtn.textContent = i18n.t('trigger');
    }

    toggleRoomSelected(checkbox) {
      return this.constructor.roomController.toggleRoomSelected(this, checkbox);
    }

    updateSelectAllState(container) {
      return this.constructor.roomController.updateSelectAllState(container);
    }

    refreshToLevelOptions(fromSelect) {
      return this.constructor.roomController.refreshToLevelOptions(fromSelect);
    }

    refreshBatchToLevelOptions(container) {
      return this.constructor.roomController.refreshBatchToLevelOptions(container);
    }

    toggleAllRooms(container, group) {
      return this.constructor.roomController.toggleAllRooms(this, container, group);
    }

    refreshRoomLevels(container) {
      return this.constructor.roomController.refreshRoomLevels(this, container);
    }

    applyBatchFromLevel(container) {
      return this.constructor.roomController.applyBatchFromLevel(this, container);
    }

    applyBatchToLevel(container) {
      return this.constructor.roomController.applyBatchToLevel(this, container);
    }

    scheduleCalculate(container) {
      return this.constructor.calculationController.scheduleCalculate(this, container);
    }

    clearPendingCalculate() {
      return this.constructor.calculationController.clearPendingCalculate(this);
    }

    flushScheduledCalculate(container) {
      return this.constructor.calculationController.flushScheduledCalculate(this, container);
    }

    calculateSelectedRooms(container) {
      return this.constructor.calculationController.calculateSelectedRooms(this, container);
    }

    refreshResultDisplay(container) {
      return this.constructor.calculationController.refreshResultDisplay(this, container);
    }

    escapeCsvCell(value) {
      return this.constructor.results.escapeCsvCell(value);
    }

    formatCompactNumber(value) {
      return this.constructor.results.formatCompactNumber(value);
    }

    formatMaterialCount(itemHrid, value) {
      return this.constructor.results.formatMaterialCount(itemHrid, value);
    }

    getMaterialEntries(materials) {
      return this.constructor.results.getMaterialEntries(this, materials);
    }

    getMaterialSummary(materialEntries) {
      return this.constructor.results.getMaterialSummary(materialEntries);
    }

    exportCsv(container) {
      this.constructor.results.exportCsv(this, container);
    }

    formatMaterialResultLine(entry, useHrid) {
      return this.constructor.results.formatMaterialResultLine(entry, useHrid);
    }

    displayResults(container, materials, roomDetails) {
      this.constructor.results.displayResults(this, container, materials, roomDetails);
    }

    getRoomLevelsFromUI() {
      return this.constructor.roomController.getRoomLevelsFromUI(this);
    }
  }

  // house-calculator-launcher
  class HouseCalculatorLauncher {
    static ctx = null;

    static configure(ctx) {
      this.ctx = ctx;
    }

    constructor() {
      this.isInitialized = false;
      this.domObserver = null;
      this.houseCalculatorUI = null;
    }

    getHouseCalculatorUI() {
      return this.houseCalculatorUI;
    }

    addTriggerButton() {
      const {GameUiAdapter, i18n} = this.constructor.ctx;
      const housePanel = GameUiAdapter.query('housePanel');
      if (!housePanel || document.getElementById('mst-hccp-house-calculator-trigger')) return;

      const targetButton = GameUiAdapter.query('gameButton', housePanel) || housePanel.querySelector('button');
      let buttonContainer = GameUiAdapter.query('houseButtonContainer', housePanel) || targetButton?.parentElement;
      if (!buttonContainer) {
        const title = GameUiAdapter.query('houseTitle', housePanel);
        buttonContainer = document.createElement('div');
        buttonContainer.className = 'mst-hccp-trigger-container';
        title?.insertAdjacentElement('afterend', buttonContainer);
      }

      if (!buttonContainer) return;

      const triggerBtn = document.createElement('button');
      triggerBtn.className = targetButton?.className || 'Button_button__1Fe9z';
      triggerBtn.id = 'mst-hccp-house-calculator-trigger';
      triggerBtn.style.marginLeft = '10px';
      triggerBtn.textContent = i18n.t('trigger');

      triggerBtn.addEventListener('click', async () => this.openCalculator(triggerBtn));

      buttonContainer.style.display = 'flex';
      buttonContainer.style.justifyContent = 'center';
      buttonContainer.style.alignItems = 'center';
      buttonContainer.style.flexWrap = 'wrap';
      buttonContainer.style.gap = '10px';
      triggerBtn.style.marginLeft = targetButton ? '0' : '';
      if (targetButton?.parentNode === buttonContainer) {
        buttonContainer.insertBefore(triggerBtn, targetButton.nextSibling);
      } else {
        buttonContainer.appendChild(triggerBtn);
      }
    }

    async openCalculator(triggerBtn = null) {
      const {DataHub, i18n, marketDataService, houseCalculator, houseDetails, HouseCalculatorUI, Notifier} =
        this.constructor.ctx;
      try {
        if (!this.isInitialized) {
          if (triggerBtn) triggerBtn.textContent = i18n.t('marketLoading');
          DataHub.initClientDataFromCache();
          if (!DataHub.hasHouseRoomData()) {
            throw new Error('initClientData houseRoomDetailMap is not ready');
          }
          await marketDataService.load();
          this.houseCalculatorUI = new HouseCalculatorUI(houseDetails, houseCalculator, marketDataService);
          this.houseCalculatorUI.create();
          this.isInitialized = true;
          if (triggerBtn) triggerBtn.textContent = i18n.t('trigger');
          return;
        }

        if (!document.getElementById('mst-hccp-house-calculator')) this.houseCalculatorUI.create();
      } catch (error) {
        if (triggerBtn) triggerBtn.textContent = i18n.t('trigger');
        console.error('[HCCP] 初始化失敗:', error);
        Notifier.alert(i18n.t('initFailed'), 'error');
      }
    }

    observeDOM() {
      const {CONFIG, GameUiAdapter, utils} = this.constructor.ctx;
      if (!CONFIG.isGameSite || this.domObserver) return;
      this.domObserver = utils.observeBody(() => {
        // 檢查房屋面板是否存在，以及我們的觸發按鈕是否不存在。
        if (GameUiAdapter.query('housePanel') && !document.getElementById('mst-hccp-house-calculator-trigger')) {
          this.addTriggerButton();
        }
      });
      window.addEventListener('beforeunload', () => this.domObserver?.disconnect(), {once: true});
    }
  }

  var MST_LABYRINTH_SUPPLY_CSS = String.raw`.mst-labyrinth-supply{display:flex;justify-content:center;margin:0 0 .25rem}
.mst-labyrinth-supply-toggle:not([class*=Button_button__]){min-height:var(--button-height-normal, 1.875rem);padding:0 .625rem;box-sizing:border-box;border:1px solid var(--color-midnight-100, #454771);border-radius:var(--radius-sm, .25rem);background:var(--color-midnight-500, #2c2e45);color:var(--color-text-dark-mode, #e7e7e7);font:inherit;font-size:var(--font-size-base, .875rem);white-space:nowrap;cursor:pointer}
.mst-labyrinth-supply-toggle:not([class*=Button_button__]):hover{border-color:var(--color-space-300, #98a7e9);background:var(--color-midnight-400, #323450)}
.mst-labyrinth-supply-popover{position:fixed;z-index:var(--mst-z-popup);display:flex;min-width:12rem;flex-direction:column;gap:.35rem;padding:.5rem;box-sizing:border-box;border:1px solid var(--color-midnight-100, #454771);border-radius:var(--radius-sm, .25rem);background:var(--color-midnight-600, #27283b);box-shadow:var(--shadow-md, 0 .35rem 1rem rgba(0, 0, 0, .4));font-family:Roboto,Helvetica,Arial,sans-serif}
.mst-labyrinth-supply-popover[hidden]{display:none}
.mst-labyrinth-supply-popover-title{color:var(--color-text-dark-mode, #e7e7e7);font-size:var(--font-size-small, .75rem);font-weight:600;text-align:center}
.mst-labyrinth-supply-popover-grid{display:grid;grid-template-columns:repeat(5,2rem);gap:.3rem;justify-content:center}
.mst-labyrinth-supply-popover-grid button{min-height:2rem;padding:0;border:1px solid var(--color-midnight-100, #454771);border-radius:var(--radius-sm, .25rem);background:var(--color-midnight-500, #2c2e45);color:var(--color-text-dark-mode, #e7e7e7);font:inherit;font-size:var(--font-size-base, .875rem);cursor:pointer}
.mst-labyrinth-supply-popover-grid button:hover{border-color:var(--color-space-300, #98a7e9);background:var(--color-midnight-400, #323450)}`;

  // 迷宮入場配置未設定物品時，按專家檔位道具兜底（與遊戲 LabyrinthSupplyItems 的 expert 系列一致）。
  const LABYRINTH_DEFAULT_ITEMS = Object.freeze({
    torch: '/items/expert_torch',
    shroud: '/items/expert_shroud',
    beacon: '/items/expert_beacon',
    teaCrate: '/items/expert_tea_crate',
    coffeeCrate: '/items/expert_coffee_crate',
    foodCrate: '/items/expert_food_crate'
  });

  // 道具攜帶上限：角色未解鎖對應迷宮升級時使用遊戲基礎上限（LabyrinthBaseTorchCap 等）。
  const LABYRINTH_BASE_CAPS = Object.freeze({torch: 100, shroud: 4, beacon: 5});

  // 遊戲入場券上限固定為 5（迷宮入口“入場券: {{current}} / {{max}}”的 max 為硬編碼）。
  const LABYRINTH_MAX_ENTRIES = 5;

  const SUPPLY_KEYS = Object.freeze([
    'torch', 'shroud', 'beacon'
  ]);
  const CRATE_KEYS = Object.freeze([
    'teaCrate', 'coffeeCrate', 'foodCrate'
  ]);

  // 每次入場各補給箱消耗 1 個（茶箱/咖啡箱/食物箱），道具按攜帶上限補足。
  function calculateLabyrinthSupply(config, ownedCounts, entryCount) {
    const count = Math.max(1, Math.floor(Number(entryCount) || 0));
    const owned = ownedCounts || {};
    const items = [];
    for (const key of SUPPLY_KEYS) {
      const entry = config?.[key];
      if (!entry?.hrid) continue;
      const cap = Math.max(0, Number(entry.cap) || 0);
      const missing = Math.max(0, cap * count - Number(owned[entry.hrid] || 0));
      if (missing > 0) items.push({itemId: entry.hrid, quantity: missing});
    }
    for (const key of CRATE_KEYS) {
      const entry = config?.[key];
      if (!entry?.hrid) continue;
      const missing = Math.max(0, count - Number(owned[entry.hrid] || 0));
      if (missing > 0) items.push({itemId: entry.hrid, quantity: missing});
    }
    return items;
  }

  // labyrinth-supply-config
  const labyrinthSupplyConfig = {
    getConfig(feature) {
      const {CharacterDataService} = feature.ctx;
      const raw = CharacterDataService.raw || {};
      const info = raw.characterInfo || {};
      const setting = raw.characterSetting || {};
      const cap = (name) => {
        const value = Number(info[`labyrinth${name}Cap`]);
        return value > 0 ? value : LABYRINTH_BASE_CAPS[name.toLowerCase()];
      };
      const pick = (name) => setting[`labyrinth${name}Hrid`] || LABYRINTH_DEFAULT_ITEMS[name.toLowerCase()];
      return {
        torch: {hrid: pick('Torch'), cap: cap('Torch')},
        shroud: {hrid: pick('Shroud'), cap: cap('Shroud')},
        beacon: {hrid: pick('Beacon'), cap: cap('Beacon')},
        teaCrate: {hrid: pick('TeaCrate')},
        coffeeCrate: {hrid: pick('CoffeeCrate')},
        foodCrate: {hrid: pick('FoodCrate')}
      };
    }
  };

  // labyrinth-supply-cart
  const labyrinthSupplyCart = {
    addToCart(feature, entryCount) {
      const {CharacterDataService, DataHub, MarketMateBridge, i18n, Notifier} = feature.ctx;
      if (!MarketMateBridge.isReady()) {
        Notifier.toast(i18n.t('marketMateUnavailable'), 'warning');
        return;
      }
      const config = labyrinthSupplyConfig.getConfig(feature);
      const owned = {};
      for (const key of [
        ...SUPPLY_KEYS, ...CRATE_KEYS
      ]) {
        const hrid = config[key].hrid;
        if (hrid && owned[hrid] == null) owned[hrid] = CharacterDataService.getInventoryCount(hrid, 0);
      }
      const quantities = calculateLabyrinthSupply(config, owned, entryCount);
      if (!quantities.length) {
        Notifier.toast(i18n.t('labyrinthSupplyNothingMissing'), 'info');
        return;
      }
      const items = quantities.map(({itemId, quantity}) => ({
        itemId,
        name: DataHub.resolveItemName(itemId),
        iconRef: itemId,
        quantity,
        source: 'mst_labyrinth'
      }));
      const response = MarketMateBridge.addToCart(items);
      if (!response?.ok) {
        Notifier.toast(response?.error || i18n.t('labyrinthSupplyAddFailed'), 'error');
        return;
      }
      const total = quantities.reduce((sum, item) => sum + item.quantity, 0);
      Notifier.toast(i18n.t('labyrinthSupplyDone', quantities.length, total.toLocaleString(i18n.locale)), 'success');
    }
  };

  // labyrinth-supply-popover
  const labyrinthSupplyPopover = {
    show(feature) {
      if (!feature.popover || !feature.wrapper?.isConnected) return;
      feature.popover.hidden = false;
      this.position(feature);
    },

    hide(feature) {
      if (feature.popover) feature.popover.hidden = true;
    },

    position(feature) {
      const popover = feature.popover;
      const trigger = feature.wrapper?.querySelector('.mst-labyrinth-supply-toggle');
      if (!popover || !trigger) return;
      const viewport = window.visualViewport;
      const viewportLeft = viewport?.offsetLeft || 0;
      const viewportTop = viewport?.offsetTop || 0;
      const viewportRight = viewportLeft + (viewport?.width || window.innerWidth);
      const viewportBottom = viewportTop + (viewport?.height || window.innerHeight);
      const margin = 8;
      const gap = 6;
      const triggerRect = trigger.getBoundingClientRect();
      const popoverRect = popover.getBoundingClientRect();
      const left = Math.max(
        viewportLeft + margin,
        Math.min(
          triggerRect.left + triggerRect.width / 2 - popoverRect.width / 2,
          viewportRight - popoverRect.width - margin
        )
      );
      // 優先顯示在按鈕上方，空間不足時再放到下方。
      const aboveTop = triggerRect.top - popoverRect.height - gap;
      const belowTop = triggerRect.bottom + gap;
      const top =
        aboveTop >= viewportTop + margin ? aboveTop : Math.min(belowTop, viewportBottom - popoverRect.height - margin);
      popover.style.left = `${left}px`;
      popover.style.top = `${top}px`;
    }
  };

  // labyrinth-supply-feature
  class LabyrinthSupplyFeature {
    static ctx = null;

    static configure(ctx) {
      this.ctx = ctx;
    }

    constructor() {
      this.ctx = LabyrinthSupplyFeature.ctx;
      this.bodyObserver = null;
      this.anchor = null;
      this.wrapper = null;
      this.popover = null;
      this.hideTimer = null;
      this.lastTogglePointerAt = 0;
    }

    init() {
      const {CONFIG, LanguageEvents, pageWindow, utils} = this.ctx;
      if (!CONFIG.isGameSite) return;
      // 同一頁面只允許一個迷宮補給例項活動：除錯注入、舊指令碼殘留等並存時，
      // 多個例項會互相清理對方插入的按鈕導致按鈕持續閃爍，先到先得。
      // 標記必須寫在頁面 window（unsafeWindow）上：油猴沙箱的 window 與頁面 window
      // 是兩個物件，寫在沙箱 window 上時其他指令碼副本（另一個沙箱）看不到該標記。
      if (pageWindow.__MST_LABYRINTH_SUPPLY_OWNER__) return;
      pageWindow.__MST_LABYRINTH_SUPPLY_OWNER__ = true;
      // 舊版本指令碼可能殘留舊 CSS（如按鈕 fixed 定位），主動覆蓋為當前樣式，避免升級後樣式不更新。
      const existingStyle = document.getElementById('mst-labyrinth-supply-style');
      if (existingStyle) existingStyle.textContent = MST_LABYRINTH_SUPPLY_CSS;
      else StyleService.ensure('mst-labyrinth-supply-style', MST_LABYRINTH_SUPPLY_CSS);
      this.bodyObserver = utils.observeBody(() => this.sync());
      LanguageEvents.subscribe(() => this.updateLabels());
    }

    sync() {
      const {GameUiAdapter} = this.ctx;
      const panel = GameUiAdapter.query('labyrinthPanel');
      // 按鈕容器與入口屏是迷宮標籤頁下的平級節點（真實 DOM 位於 labyrinthTab > bottomArea > infoContainer 內），
      // 且只有入口屏才渲染（進行中的迷宮無此容器），直接在面板內查詢即可。
      const buttonsContainer = panel?.querySelector('[class*="LabyrinthPanel_buttonsContainer"]') || null;
      // 只認真正的“進入迷宮”按鈕：補充補給按鈕也複用 Button_ 類，若把其他例項的
      // 補充補給按鈕錯當錨點，兩個例項會互相插拔按鈕導致持續閃爍，必須排除。
      const candidates = buttonsContainer ? [
            ...buttonsContainer.querySelectorAll('button')
          ] : [];
      const enterButton =
        candidates.find(
          (button) => /Button_/.test(button.className) && !button.classList.contains('mst-labyrinth-supply-toggle')
        ) ||
        candidates.find((button) => !button.classList.contains('mst-labyrinth-supply-toggle')) ||
        null;
      if (!enterButton) {
        this.teardown();
        return;
      }
      // “進入迷宮”按鈕預設用 large 檔（2.25rem 高），視覺偏高；
      // 移除 Button_large 變體即回落到遊戲官方 normal 檔高度（1.875rem），遊戲重渲染後由本方法重新維持。
      const buttonNames = String(enterButton.className || '').split(/\s+/);
      const largeIndex = buttonNames.findIndex((name) => name.startsWith('Button_large__'));
      if (largeIndex >= 0) {
        buttonNames.splice(largeIndex, 1);
        enterButton.className = buttonNames.join(' ');
      }
      // 按鈕與懸浮窗都隨遊戲面板佈局：按鈕插入“進入迷宮”按鈕後方的文件流內（與房屋計算器觸發按鈕一致），
      // 懸浮窗是臨時浮層才掛 body；遊戲重渲染清掉按鈕節點時由觀察器重建。
      if (enterButton !== this.anchor || !this.wrapper?.isConnected) {
        this.teardown();
        this.anchor = enterButton;
        this.build(enterButton);
      }
    }

    build(anchor) {
      const {i18n} = this.ctx;
      // 複用遊戲按鈕外觀：基礎類從頁面現有按鈕動態提取（遊戲更新 CSS 雜湊後仍能跟隨），
      // 與“進入迷宮”按鈕同為官方 normal 檔尺寸；不追加 small/large 變體。
      const gameButtonClass = (() => {
        const found = new Set();
        this.ctx.GameUiAdapter.query('labyrinthPanel')
          ?.querySelectorAll('button[class*="Button_"]')
          .forEach((button) => {
            String(button.className || '')
              .split(/\s+/)
              .forEach((name) => {
                if (name.startsWith('Button_button__')) found.add(name);
              });
          });
        return [
            ...found
          ].find((name) => name.startsWith('Button_button__')) || 'Button_button__1Fe9z';
      })();
      this.wrapper = document.createElement('div');
      this.wrapper.className = 'mst-labyrinth-supply';
      const label = i18n.t('labyrinthSupply');
      this.wrapper.innerHTML = `<button type="button" class="mst-labyrinth-supply-toggle ${gameButtonClass}" title="${label}">${label}</button>`;
      // 先清掉按鈕容器內可能殘留的同名按鈕（頁面同時存在多個指令碼例項時避免互相干擾）。
      anchor.parentElement?.querySelectorAll('.mst-labyrinth-supply').forEach((element) => element.remove());
      // 插入按鈕容器文件流（“進入迷宮”按鈕正上方），隨面板佈局自動排布，不會漂移。
      anchor.insertAdjacentElement('beforebegin', this.wrapper);
      const toggle = this.wrapper.querySelector('.mst-labyrinth-supply-toggle');
      // 點選切換小窗：pointerup 先於觸屏點選時瀏覽器合成的 mouseenter 觸發（合成序列為
      // touchstart → touchend → pointerup → mouseenter → mousedown → mouseup → click），
      // 若沿用 click 切換，彈窗會先被合成 mouseenter 顯示、再被 click 判定“已顯示”而立即
      // 隱藏，移動端表現為點了沒反應；pointerup 切換時彈窗狀態尚未被合成事件改動。
      toggle.addEventListener('pointerup', (event) => {
        event.stopPropagation();
        this.lastTogglePointerAt = Date.now();
        this.togglePopover();
      });
      // 鍵盤（Enter/空格）只觸發 click，作為切換兜底；pointerup 已切換的同一點選跳過去重。
      toggle.addEventListener('click', (event) => {
        event.stopPropagation();
        if (Date.now() - (this.lastTogglePointerAt || 0) < 500) return;
        this.togglePopover();
      });

      this.popover = document.createElement('div');
      this.popover.className = 'mst-labyrinth-supply-popover';
      this.popover.setAttribute('role', 'menu');
      this.popover.hidden = true;
      document.body.appendChild(this.popover);
      this.renderPopover();

      // 懸浮顯示小窗；從按鈕移向小窗期間短暫延遲隱藏，避免視窗抖動。
      // 觸屏點選會合成 mouseenter（在 pointerup 之後），500ms 內忽略，避免覆蓋點選切換的結果。
      this.wrapper.addEventListener('mouseenter', () => {
        if (Date.now() - (this.lastTogglePointerAt || 0) < 500) return;
        this.scheduleShow(0);
      });
      this.wrapper.addEventListener('mouseleave', () => this.scheduleHide());
      this.popover.addEventListener('mouseenter', () => {
        if (Date.now() - (this.lastTogglePointerAt || 0) < 500) return;
        this.scheduleShow(0);
      });
      this.popover.addEventListener('mouseleave', () => this.scheduleHide());
      document.addEventListener(
        'pointerdown',
        (this.outsidePointerDownHandler = (event) => {
          if (!this.wrapper?.contains(event.target) && !this.popover?.contains(event.target)) this.hidePopover();
        })
      );
      // 捕獲階段監聽滾動與視口變化：懸浮窗顯示期間跟隨按鈕重新定位（按鈕本體在文件流內無需處理）。
      this.repositionHandler = () => {
        if (!this.popover?.hidden) labyrinthSupplyPopover.position(this);
      };
      document.addEventListener('scroll', this.repositionHandler, true);
      window.addEventListener('resize', this.repositionHandler);
      window.visualViewport?.addEventListener('resize', this.repositionHandler);
      window.visualViewport?.addEventListener('scroll', this.repositionHandler);
      this.updateLabels();
    }

    renderPopover() {
      const {i18n, TemplateRenderer} = this.ctx;
      const options = Array.from(
        {length: LABYRINTH_MAX_ENTRIES},
        (_, index) => TemplateRenderer.html`
  <button type="button" role="menuitem" data-entry-count=${String(index + 1)}
      title=${i18n.t('labyrinthSupplyRunTitle', String(index + 1))}>${index + 1}</button>`
      );
      TemplateRenderer.render(
        () => TemplateRenderer.html`
  <div class="mst-labyrinth-supply-popover-title">${i18n.t('labyrinthSupplyPopoverTitle')}</div>
  <div class="mst-labyrinth-supply-popover-grid">${options}</div>
`,
        this.popover
      );
      this.popover.querySelectorAll('[data-entry-count]').forEach((button) => {
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          labyrinthSupplyCart.addToCart(this, Number(button.dataset.entryCount));
          this.hidePopover();
        });
      });
    }

    scheduleShow(delay) {
      clearTimeout(this.hideTimer);
      this.hideTimer = null;
      const show = () => labyrinthSupplyPopover.show(this);
      if (delay > 0) this.hideTimer = setTimeout(show, delay);
      else show();
    }

    scheduleHide() {
      clearTimeout(this.hideTimer);
      this.hideTimer = setTimeout(() => this.hidePopover(), 120);
    }

    togglePopover() {
      if (this.popover?.hidden) this.scheduleShow(0);
      else this.hidePopover();
    }

    hidePopover() {
      clearTimeout(this.hideTimer);
      this.hideTimer = null;
      labyrinthSupplyPopover.hide(this);
    }

    teardown() {
      if (this.hideTimer) {
        clearTimeout(this.hideTimer);
        this.hideTimer = null;
      }
      if (this.outsidePointerDownHandler) {
        document.removeEventListener('pointerdown', this.outsidePointerDownHandler);
        this.outsidePointerDownHandler = null;
      }
      if (this.repositionHandler) {
        document.removeEventListener('scroll', this.repositionHandler, true);
        window.removeEventListener('resize', this.repositionHandler);
        window.visualViewport?.removeEventListener('resize', this.repositionHandler);
        window.visualViewport?.removeEventListener('scroll', this.repositionHandler);
        this.repositionHandler = null;
      }
      this.popover?.remove();
      this.popover = null;
      this.wrapper?.remove();
      this.wrapper = null;
      this.anchor = null;
    }

    updateLabels() {
      const {i18n} = this.ctx;
      const toggle = this.wrapper?.querySelector('.mst-labyrinth-supply-toggle');
      if (!toggle) return;
      const label = i18n.t('labyrinthSupply');
      toggle.textContent = label;
      toggle.title = i18n.t('labyrinthSupplyTitle');
      // 懸浮小窗內容只在構建時渲染一次，語言切換後標題與入場次數按鈕提示也要跟著更新。
      const title = this.popover?.querySelector('.mst-labyrinth-supply-popover-title');
      if (title) title.textContent = i18n.t('labyrinthSupplyPopoverTitle');
      this.popover?.querySelectorAll('[data-entry-count]').forEach((button) => {
        button.title = i18n.t('labyrinthSupplyRunTitle', String(button.dataset.entryCount));
      });
    }
  }

  var MST_MARKETPLACE_CART_CSS = String.raw`.mst-marketplace-cart{display:inline-flex}
.mst-marketplace-cart-button:not([class*=Button_button__]){min-height:var(--button-height-normal, 1.875rem);padding:0 .625rem;box-sizing:border-box;border:1px solid var(--color-midnight-100, #454771);border-radius:var(--radius-sm, .25rem);background:var(--color-midnight-500, #2c2e45);color:var(--color-text-dark-mode, #e7e7e7);font:inherit;font-size:var(--font-size-base, .875rem);white-space:nowrap;cursor:pointer}
.mst-marketplace-cart-button:not([class*=Button_button__]):hover{border-color:var(--color-space-300, #98a7e9);background:var(--color-midnight-400, #323450)}`;

  // 市場加購固定數量：把“市場當前物品”加入購物車 1 個。
  const MARKETPLACE_CART_QUANTITY = 1;

  // marketplace-cart-state
  // 從錨點 DOM 的 React fiber 鏈向上找 MarketplacePanel 類元件例項並返回其 state；
  // 遊戲原始碼（MarketplacePanel 元件）該 state 同時含 marketListingsView/itemHrid/enhancementLevel，
  // 訂單簿檢視下 enhancementLevel 就是當前檢視的強化等級，可增強物品據此保留等級。
  function readMarketplacePanelState(fiber) {
    let current = fiber;
    while (current) {
      const instance = current.stateNode;
      const state = instance?.state;
      if (
        state &&
        typeof state === 'object' &&
        'marketListingsView' in state &&
        'itemHrid' in state &&
        'enhancementLevel' in state &&
        typeof instance.handleRefresh === 'function'
      ) {
        return state;
      }
      current = current.return;
    }
    return null;
  }

  // marketplace-cart-feature
  class MarketplaceCartFeature {
    static ctx = null;

    static configure(ctx) {
      this.ctx = ctx;
    }

    constructor() {
      this.ctx = MarketplaceCartFeature.ctx;
      this.bodyObserver = null;
      this.anchor = null;
      this.wrapper = null;
    }

    init() {
      const {CONFIG, LanguageEvents, pageWindow, utils} = this.ctx;
      if (!CONFIG.isGameSite) return;
      // 同一頁面只允許一個市場加購例項活動：除錯注入、舊指令碼殘留等並存時，
      // 多個例項會互相清理對方插入的按鈕導致按鈕持續閃爍，先到先得。
      // 標記必須寫在頁面 window（unsafeWindow）上：油猴沙箱的 window 與頁面 window
      // 是兩個物件，寫在沙箱 window 上時其他指令碼副本（另一個沙箱）看不到該標記。
      if (pageWindow.__MST_MARKETPLACE_CART_OWNER__) return;
      pageWindow.__MST_MARKETPLACE_CART_OWNER__ = true;
      StyleService.ensure('mst-marketplace-cart-style', MST_MARKETPLACE_CART_CSS);
      this.bodyObserver = utils.observeBody(() => this.sync());
      LanguageEvents.subscribe(() => this.updateLabel());
    }

    sync() {
      const {DataHub, GameUiAdapter} = this.ctx;
      const container = GameUiAdapter.query('marketplaceNavButtons');
      // 遊戲原始碼 renderMarketListingsNavigationButtons 的 children 順序固定為
      // [viewAllItems, viewAllEnhancementLevels, refresh]，重新整理按鈕恆為最後一個；
      // 排除本模組按鈕後取最後一個（React 重渲染清掉本模組按鈕後即重新整理按鈕本身）。
      const candidates = container ? [
            ...container.querySelectorAll('button')
          ] : [];
      const refreshButton =
        [
          ...candidates
        ]
          .reverse()
          .find((button) => {
            if (button.classList.contains('mst-marketplace-cart-button')) return false;
            // 只認 React 渲染的按鈕：其他指令碼克隆/注入的按鈕（如生產採集增強指令碼的
            // market-cart-btn）沒有 __reactFiber 關聯，用作錨點後讀不到 MarketplacePanel
            // state，點選會誤報“當前沒有可加入購物車的市場物品”。
            return DataHub.getReactFiber(button) != null;
          }) || null;
      if (!refreshButton) {
        this.teardown();
        return;
      }
      // 按鈕插入重新整理按鈕後方的文件流內（與迷宮補充補給同一做法），隨面板佈局自動排布；
      // 遊戲重渲染清掉按鈕節點時由觀察器重建。
      if (refreshButton !== this.anchor || !this.wrapper?.isConnected) {
        this.teardown();
        this.anchor = refreshButton;
        this.build(refreshButton);
      }
    }

    build(anchor) {
      const {i18n} = this.ctx;
      // 複用遊戲按鈕外觀：基礎類從導航按鈕容器現有按鈕動態提取（遊戲更新 CSS 雜湊後仍能跟隨）。
      const gameButtonClass = (() => {
        const names = [];
        anchor.parentElement?.querySelectorAll('button[class*="Button_"]').forEach((button) => {
          names.push(...String(button.className || '').split(/\s+/));
        });
        return names.find((name) => name.startsWith('Button_button__')) || 'Button_button__1Fe9z';
      })();
      this.wrapper = document.createElement('div');
      this.wrapper.className = 'mst-marketplace-cart';
      const label = i18n.t('marketplaceCart');
      this.wrapper.innerHTML = `<button type="button" class="mst-marketplace-cart-button ${gameButtonClass}" title="${label}">${label}</button>`;
      // 先清掉按鈕容器內可能殘留的同名按鈕（頁面同時存在多個指令碼例項時避免互相干擾）。
      anchor.parentElement?.querySelectorAll('.mst-marketplace-cart').forEach((element) => element.remove());
      // 插入重新整理按鈕後方的文件流內，隨面板佈局自動排布，不會漂移。
      anchor.insertAdjacentElement('afterend', this.wrapper);
      const button = this.wrapper.querySelector('.mst-marketplace-cart-button');
      button.addEventListener('click', (event) => {
        event.stopPropagation();
        this.addToCart();
      });
      this.updateLabel();
    }

    addToCart() {
      const {DataHub, i18n, MarketMateBridge, Notifier} = this.ctx;
      if (!MarketMateBridge.isReady()) {
        Notifier.toast(i18n.t('marketMateUnavailable'), 'warning');
        return;
      }
      const anchor = this.anchor;
      if (!anchor?.isConnected) return;
      const state = readMarketplacePanelState(DataHub.getReactFiber(anchor));
      const itemHrid = state?.itemHrid;
      if (!state || !itemHrid) {
        Notifier.toast(i18n.t('marketplaceCartNoItem'), 'warning');
        return;
      }
      const enhancementLevel = Math.max(0, Math.floor(Number(state.enhancementLevel) || 0));
      const name = DataHub.resolveItemName(itemHrid);
      const response = MarketMateBridge.addToCart([
        {
          itemId: itemHrid,
          enhancementLevel,
          name,
          iconRef: itemHrid,
          quantity: MARKETPLACE_CART_QUANTITY,
          source: 'mst_marketplace'
        }
      ]);
      if (!response?.ok) {
        Notifier.toast(response?.error || i18n.t('marketplaceCartAddFailed'), 'error');
        return;
      }
      const label = enhancementLevel > 0 ? `${name} +${enhancementLevel}` : name;
      Notifier.toast(i18n.t('marketplaceCartDone', label), 'success');
    }

    updateLabel() {
      const {i18n} = this.ctx;
      const button = this.wrapper?.querySelector('.mst-marketplace-cart-button');
      if (!button) return;
      const label = i18n.t('marketplaceCart');
      button.textContent = label;
      button.title = i18n.t('marketplaceCartTitle');
    }

    teardown() {
      this.wrapper?.remove();
      this.wrapper = null;
      this.anchor = null;
    }
  }

  // 佇列跟蹤器：以官方 CharacterAction.id 為準判定行動佇列變動事件。
  // 純邏輯邊界，不依賴 DOM、DataHub 或 i18n，事件文案由裝配層生成。
  // 官方合併語義（main.*.chunk.js handleMessageActionsUpdated，v1.20260814.0）：
  // endCharacterActions 中 isDone=true 的行動從佇列移除，其餘按 id upsert，
  // 最後 partyID 非 0（組隊/戰鬥行動）排在前、partyID 為 0 的在後、各組按 ordinal 升序。

  // 佇列排序：partyID 非 0（組隊/戰鬥行動）在前，個人行動在後，同組按 ordinal 升序。
  function sortActions(actions) {
    return [
      ...actions
    ].sort((a, b) => {
      if (a.partyID !== 0 && b.partyID === 0) return -1;
      if (a.partyID === 0 && b.partyID !== 0) return 1;
      return a.ordinal - b.ordinal;
    });
  }

  class QueueChangeTracker {
    constructor() {
      this.queue = [];
      this.currentId = null;
      this.characterId = null;
      // 進度計數基線：組隊戰鬥重新準備後從當前次數重新起算（{id, count}）。
      this.progressBaseline = null;
      // 是否拿到過全量基線：未拿到基線時佇列為空只表示"沒有資料"，不代表"佇列是空的"。
      this.hasBaseline = false;
    }

    // 記憶體態整體重置：切角色時舊任務的跟蹤狀態立即釋放，不保留跨任務殘留。
    reset(characterId = null) {
      this.queue = [];
      this.currentId = null;
      this.characterId = characterId;
      this.progressBaseline = null;
      this.hasBaseline = false;
    }

    // 基線快照：頁面載入 / 斷線重連時以 init_character_data 全量重建，不產生事件。
    setQueue(actions, characterId = null) {
      if (characterId != null) this.characterId = characterId;
      this.queue = sortActions(Array.isArray(actions) ? actions.filter(Boolean) : []);
      this.currentId = this.queue[0]?.id ?? null;
      this.progressBaseline = null;
      this.hasBaseline = true;
    }

    // 官方 actions_updated 增量合併。
    // 返回事件 {type, completedTask, newTask, queue, isEmpty} 或 null：
    // - 隊首換成另一個任務即視為一次任務開始（type='started'）：被其他任務頂掉、被擠下去的
    //   任務重新回到隊首、有限任務未達上限被移除、空佇列入隊都算；
    // - 上一任務確實以 isDone 結束且不算取消時升級為 type='completed'，可再播報完成通知；
    // 同一 id 返回 null：多步任務期間官方持續推送 action_completed 但 id 不變，迷宮等無限
    // 行動在隊首連續重複執行也走這條，都屬於“同一任務還在跑”，不是重新開始。
    applyActionsUpdate(endCharacterActions) {
      const updates = Array.isArray(endCharacterActions) ? endCharacterActions.filter(Boolean) : [];
      if (!updates.length) return null;
      const prevCurrentId = this.currentId;
      const doneIds = new Set();
      for (const update of updates) {
        if (update.isDone) doneIds.add(update.id);
      }
      this.queue = this.queue.filter((action) => !doneIds.has(action.id));
      for (const update of updates) {
        if (update.isDone) continue;
        const index = this.queue.findIndex((action) => action.id === update.id);
        if (index >= 0) this.queue[index] = update;
        else this.queue.push(update);
      }
      this.queue = sortActions(this.queue);
      this.currentId = this.queue[0]?.id ?? null;
      if (this.currentId !== prevCurrentId) this.progressBaseline = null;
      if (prevCurrentId === this.currentId) return null;
      const endedTask =
        prevCurrentId != null && doneIds.has(prevCurrentId)
          ? updates.find((update) => update.id === prevCurrentId) || null
          : null;
      const base = {
        newTask: this.queue[0] || null,
        queue: this.queue.slice(),
        isEmpty: this.queue.length === 0
      };
      // 取消啟發：有限次數任務在未達到上限時被移除，按使用者取消處理——不報完成，只報任務開始。
      // 無上限任務（戰鬥/迷宮等）與已完成任務無法區分取消，一律按任務結束上報。
      const cancelled = !!endedTask?.hasMaxCount && Number(endedTask.currentCount ?? 0) < Number(endedTask.maxCount ?? 0);
      if (!endedTask || cancelled) return {...base, type: 'started', completedTask: null};
      return {...base, type: 'completed', completedTask: endedTask};
    }

    // 官方 action_completed：單次行動完成明細（含掉落、經驗）。
    // 同 id 只更新進度返回 null；isDone=true 時按完成處理（單步任務可能只有該訊息沒有移除增量）。
    applyActionCompleted(endCharacterAction) {
      const action = endCharacterAction;
      if (!action || typeof action !== 'object') return null;
      if (!action.isDone) {
        const index = this.queue.findIndex((item) => item.id === action.id);
        if (index >= 0) this.queue[index] = action;
        return null;
      }
      return this.applyActionsUpdate([
        action
      ]);
    }

    getCurrentTask() {
      return this.queue[0] || null;
    }

    // 組隊戰鬥會話重置（本方角色重新準備）時呼叫：記錄當前任務的已完成為基線，
    // 後續進度通知按會話內增量統計。官方在同一條組隊行動上持續累加 currentCount，
    // 重新準備不會更換 id，不重置基線則進度次數會一直累計。
    resetProgressBaseline() {
      const task = this.queue[0];
      if (!task) return;
      this.progressBaseline = {id: task.id, count: Number(task.currentCount ?? 0)};
    }

    // 進度通知的已完成次數：當前任務存在基線（且未回退）時返回會話內增量，否則返回原始累計值。
    getProgressCount(task) {
      if (!task) return 0;
      const current = Number(task.currentCount ?? 0);
      const baseline = this.progressBaseline;
      if (baseline && baseline.id === task.id && current >= baseline.count) return current - baseline.count;
      return current;
    }

    getQueuePreview(count) {
      return this.queue.slice(0, count);
    }

    getQueueLength() {
      return this.queue.length;
    }

    // 等待執行的任務：排除隊首正在執行的行動（進度/完成/開始通知的佇列概覽都用這個口徑）。
    getWaitingQueuePreview(count) {
      return this.queue.slice(1, 1 + count);
    }

    getWaitingQueueLength() {
      return Math.max(0, this.queue.length - 1);
    }
  }

  // 渠道請求構造與推送限速：純邏輯邊界，不依賴 DOM 與 DataHub。
  // 簽名演算法按官方文件核對：
  // - 釘釘：sign = urlencode(base64(HmacSHA256(key=secret, msg="{毫秒時間戳}\n{secret}")))，追加在 URL 引數。
  // - 飛書：sign = base64(HMAC-SHA256(key="{秒時間戳}\n{secret}", msg=空))，放請求頭 X-Lark-Request-Timestamp/Sign。
  //   注意飛書官方示例是“以待籤串為金鑰、訊息體為空”，與釘釘的 key=secret 相反；
  //   shell 裡 `openssl dgst -hmac "$SECRET"`（key=secret）與官方 Python 口徑不一致，實現以官方文件為準。
  // - 企業微信：無簽名環節。

  const CHANNEL_LIMITS = {
    // 釘釘 text.content 最短 1、最長 500 字元（按字元截斷）。
    dingtalk: {maxChars: 500},
    // 企業微信官方限制請求體 4096 位元組，text.content 按 2048 位元組保守截斷（UTF-8 位元組）。
    wecom: {maxBytes: 2048},
    // 飛書請求體不能超過 20KB。
    feishu: {maxBytes: 20 * 1024}
  };

  // 按字元截斷，保留 UTF-16 碼元完整（用於釘釘字元數限制）。
  function truncateByChars(text, maxChars) {
    const value = String(text ?? '');
    if (value.length <= maxChars) return value;
    return value.slice(0, Math.max(1, maxChars - 1)) + '…';
  }

  function utf8ByteLength(text) {
    return new TextEncoder().encode(text).length;
  }

  // 按 UTF-8 位元組截斷，逐位元組回退避免截出殘缺多位元組字元，超長以 … 收尾。
  function truncateByUtf8Bytes(text, maxBytes) {
    const value = String(text ?? '');
    if (utf8ByteLength(value) <= maxBytes) return value;
    const bytes = new TextEncoder().encode(value);
    const suffix = new TextEncoder().encode('…');
    let end = maxBytes - suffix.length;
    while (end > 0 && (bytes[end] & 0xc0) === 0x80) end--;
    let head = bytes.slice(0, Math.max(0, end));
    return new TextDecoder().decode(head) + '…';
  }

  function truncateForChannel(channel, text) {
    const limits = CHANNEL_LIMITS[channel];
    if (!limits) return String(text ?? '');
    if (limits.maxChars != null) return truncateByChars(text, limits.maxChars);
    return truncateByUtf8Bytes(text, limits.maxBytes);
  }

  // 預設 HMAC-SHA256 助手：key 與 message 都是 UTF-8 字串，返回 base64。
  // 通過 WebCrypto 實現；環境不支援時返回 null，由呼叫方決定降級行為。
  function createDefaultHmac() {
    const subtle = globalThis.crypto?.subtle;
    const encoder = globalThis.TextEncoder ? new TextEncoder() : null;
    if (!subtle || !encoder) return null;
    return async (keyString, messageString) => {
      const key = await subtle.importKey(
        'raw',
        encoder.encode(String(keyString)),
        {name: 'HMAC', hash: 'SHA-256'},
        false,
        [
          'sign'
        ]
      );
      const signature = await subtle.sign('HMAC', key, encoder.encode(String(messageString ?? '')));
      return btoa(Array.from(new Uint8Array(signature), (byte) => String.fromCharCode(byte)).join(''));
    };
  }

  // 釘釘：加簽後把 timestamp/sign 追加到 Webhook URL；body 為純文本訊息。
  const buildDingTalkRequest = async ({url, secret, content}, {timestampMs = Date.now(), hmac} = {}) => {
    let requestUrl = String(url || '');
    if (secret) {
      const sign = await hmac(secret, `${timestampMs}\n${secret}`);
      const joiner = requestUrl.includes('?') ? '&' : '?';
      requestUrl = `${requestUrl}${joiner}timestamp=${timestampMs}&sign=${encodeURIComponent(sign)}`;
    }
    return {
      url: requestUrl,
      headers: {'Content-Type': 'application/json;charset=utf-8'},
      body: JSON.stringify({msgtype: 'text', text: {content}})
    };
  };

  // 企業微信：key 已在 URL 內，無簽名。
  function buildWeComRequest({url, content}) {
    return {
      url: String(url || ''),
      headers: {'Content-Type': 'application/json;charset=utf-8'},
      body: JSON.stringify({msgtype: 'text', text: {content}})
    };
  }

  // 飛書：簽名放請求頭（秒級時間戳），待籤串為 "{timestamp}\n{secret}"、訊息體為空。
  const buildFeishuRequest = async (
    {url, secret, content},
    {timestampSec = Math.floor(Date.now() / 1000), hmac} = {}
  ) => {
    const headers = {'Content-Type': 'application/json;charset=utf-8'};
    if (secret) {
      const sign = await hmac(`${timestampSec}\n${secret}`, '');
      headers['X-Lark-Request-Timestamp'] = String(timestampSec);
      headers['X-Lark-Request-Sign'] = sign;
    }
    return {
      url: String(url || ''),
      headers,
      body: JSON.stringify({msg_type: 'text', content: {text: content}})
    };
  };

  // 飛書 Hook 地址歸一化：允許貼上完整地址，也允許只填 hook-id（自動拼接官方地址）。
  function normalizeFeishuHookUrl(raw) {
    const value = String(raw ?? '').trim();
    if (!value) return '';
    if (/^https?:\/\//i.test(value)) return value;
    return `https://open.feishu.cn/open-apis/bot/v2/hook/${value.replace(/^\/+/, '')}`;
  }

  // 統一解析官方響應：釘釘/企微看 errcode，飛書看 code。
  function parseChannelResponse(channel, responseText) {
    let parsed = null;
    try {
      parsed = JSON.parse(String(responseText ?? ''));
    } catch {
      parsed = null;
    }
    if (!parsed || typeof parsed !== 'object') {
      const snippet = String(responseText ?? '').slice(0, 120);
      return {ok: false, code: null, msg: snippet || 'empty response'};
    }
    if (channel === 'feishu') {
      return {ok: parsed.code === 0, code: parsed.code ?? null, msg: parsed.msg || parsed.StatusCode || ''};
    }
    return {ok: parsed.errcode === 0, code: parsed.errcode ?? null, msg: parsed.errmsg || ''};
  }

  // 推送限速器：兩層限制同時生效——
  // 1) 兩次推送至少間隔 minIntervalMs（渠道推送頻率下限）；
  // 2) perMinuteLimit 每分鐘推送上限（滑動 60 秒視窗），超限時推遲到視窗最早一條過期；
  // 間隔內或等待重試期間的多次提交合併為一條、只保留最新內容；
  // 傳送失敗按 retryDelaysMs 指數退避重試，重試次數用盡後丟棄並回調 onGiveUp。
  class NotificationSender {
    constructor({send, minIntervalMs = 10000, perMinuteLimit = null, retryDelaysMs = [
        60000, 120000, 240000
      ], clock = () =>
        Date.now(), schedule = (fn, ms) => setTimeout(fn, ms), cancel = (timer) => clearTimeout(timer), onGiveUp = null} = {}) {
      this.send = send;
      this.minIntervalMs = minIntervalMs;
      this.perMinuteLimit = perMinuteLimit;
      this.retryDelaysMs = retryDelaysMs;
      this.clock = clock;
      this.schedule = schedule;
      this.cancel = cancel;
      this.onGiveUp = onGiveUp;
      this.lastSentAt = 0;
      this.sentTimestamps = [];
      this.pendingText = null;
      this.pendingTimer = null;
      this.retryTimer = null;
      this.retryCount = 0;
    }

    // 計算下次可傳送還需等待的毫秒數：最小間隔與每分鐘滑動視窗（60 秒）取較大者。
    nextWaitMs() {
      const now = this.clock();
      let wait = Math.max(0, this.lastSentAt + this.minIntervalMs - now);
      if (this.perMinuteLimit != null && this.perMinuteLimit > 0) {
        this.sentTimestamps = this.sentTimestamps.filter((timestamp) => now - timestamp < 60000);
        if (this.sentTimestamps.length >= this.perMinuteLimit) {
          wait = Math.max(wait, this.sentTimestamps[0] + 60000 - now);
        }
      }
      return wait;
    }

    // 提交一條待發內容：總是先記錄最新文案，再按限速/重試狀態安排傳送。
    submit(text) {
      this.pendingText = text;
      if (this.pendingTimer || this.retryTimer) return {queued: true};
      const wait = this.nextWaitMs();
      if (wait === 0) {
        this.pendingText = null;
        this.dispatch(text);
        return {queued: false};
      }
      this.pendingTimer = this.schedule(() => this.flush(), wait);
      return {queued: true};
    }

    flush() {
      this.pendingTimer = null;
      const text = this.pendingText;
      this.pendingText = null;
      if (text == null) return;
      const wait = this.nextWaitMs();
      if (wait > 0) {
        // 等待期間限速引數被調小等場景：仍未到可傳送時間則繼續等待。
        this.pendingText = text;
        this.pendingTimer = this.schedule(() => this.flush(), wait);
        return;
      }
      this.dispatch(text);
    }

    async dispatch(text) {
      // 傳送開始即佔坑，避免傳送期間的新提交繞過限速。
      const now = this.clock();
      this.lastSentAt = now;
      if (this.perMinuteLimit != null && this.perMinuteLimit > 0) {
        this.sentTimestamps.push(now);
      }
      try {
        await this.send(text);
        this.retryCount = 0;
      } catch (error) {
        this.handleFailure(text, error);
      }
    }

    handleFailure(text, error) {
      if (this.retryCount >= this.retryDelaysMs.length) {
        this.retryCount = 0;
        this.pendingText = null;
        this.onGiveUp?.(error);
        return;
      }
      const delay = this.retryDelaysMs[this.retryCount++];
      this.pendingText = text;
      this.retryTimer = this.schedule(() => {
        this.retryTimer = null;
        const retryText = this.pendingText;
        this.pendingText = null;
        if (retryText != null) this.dispatch(retryText);
      }, delay);
    }

    dispose() {
      if (this.pendingTimer) this.cancel(this.pendingTimer);
      if (this.retryTimer) this.cancel(this.retryTimer);
      this.pendingTimer = null;
      this.retryTimer = null;
      this.pendingText = null;
    }
  }

  var MST_SUBSCRIBE_CSS = String.raw`.mst-subscribe-form{display:flex;flex-direction:column;gap:.7rem;text-align:left}
.mst-subscribe-section-title{margin-top:.2rem;border-bottom:1px solid var(--color-midnight-100, #454771);padding-bottom:.3rem;color:var(--color-text-dark-mode, #e7e7e7);font-weight:600}
.mst-subscribe-field{display:flex;flex-direction:column;gap:.25rem}
.mst-subscribe-field>span{font-size:.85rem;opacity:.85}
.mst-subscribe-field input[type=text],.mst-subscribe-field input[type=password],.mst-subscribe-field input[type=number],.mst-subscribe-field select{box-sizing:border-box;height:var(--button-height-normal, 1.875rem);border:1px solid var(--color-midnight-100, #454771);border-radius:var(--radius-sm, .25rem);padding:.2rem .45rem;outline:0;background:var(--color-midnight-700, #20212f);color:var(--color-text-dark-mode, #e7e7e7);font:inherit;color-scheme:dark}
.mst-subscribe-form select option{background:var(--color-midnight-700, #20212f);color:var(--color-text-dark-mode, #e7e7e7)}
.mst-subscribe-row{display:flex;gap:.75rem}
.mst-subscribe-row .mst-subscribe-field{flex:1 1 0}
.mst-subscribe-detail{display:flex;flex-direction:column;gap:.7rem}
.mst-subscribe-form [hidden]{display:none!important}
.mst-subscribe-checkbox{display:inline-flex;width:100%;min-width:0;height:var(--button-height-normal, 1.875rem);box-sizing:border-box;align-items:center;justify-content:center;gap:.3rem;padding:0 .5rem;border:1px solid var(--color-midnight-100, #454771);border-radius:var(--radius-sm, .25rem);background:var(--color-midnight-500, #2c2e45);color:var(--color-space-100, #dde2f8);font-size:.9rem;cursor:pointer}
.mst-subscribe-checkbox:hover{border-color:var(--color-space-300, #98a7e9)}
.mst-subscribe-checkbox input{width:1rem!important;height:1rem!important;margin:0;flex:0 0 1rem;cursor:inherit}
.mst-subscribe-type-row{display:flex;align-items:center;gap:.6rem;flex-wrap:wrap}
.mst-subscribe-type-label{font-size:.85rem;opacity:.85}
.mst-subscribe-type-checkbox{display:inline-flex;align-items:center;gap:.3rem;font-size:.85rem;cursor:pointer}
.mst-subscribe-type-checkbox input{width:1rem!important;height:1rem!important;margin:0;cursor:inherit}
.mst-subscribe-doc-link{margin-left:.35rem;color:var(--color-space-300, #98a7e9);font-size:.8rem;text-decoration:underline;word-break:break-all}
.mst-subscribe-actions{display:flex;align-items:center;gap:.5rem}
.mst-subscribe-status{flex:1 1 auto;min-width:0;align-self:center;font-size:.8rem;opacity:.75;white-space:pre-wrap;word-break:break-all}`;

  // 訂閱通知：行動佇列變動推送到釘釘 / 企業微信 / 飛書機器人。
  // 需求與渠道限制見 docs/analysis/訂閱通知需求說明書.md。
  // 核心口徑：
  // - 只在遊戲頁面開啟期間監聽（離線變化不感知、不補推）；
  // - 以 CharacterAction.id 為準：同 id 的 action_completed 是任務內部變動不推送，
  //   只有當前任務以 isDone 結束且隊首變化才推送“完成 + 佇列前 3 項”；
  //   隊首換成新任務另有“任務開始”通知（預設開啟），附接下來 3 項等待佇列；
  // - 長時間未完成任務按週期推送進度（預設 30 分鐘）；
  // - 組隊戰鬥在同一條行動上持續累加 currentCount：監聽 party_updated，本方角色
  //   重新準備視為新戰鬥會話，進度次數從重新準備起重新計數並重置進度計時；
  // - 會話監控：監聽公共 mst:ws:state，遊戲 WebSocket 斷開（含同賬號被其他
  //   登入擠掉）時暫停定時推送，避免斷連頁面繼續用陳舊佇列資料推送；線上狀態
  //   預設未確認，WS open 或 init_character_data 才算確認線上；
  // - 佇列跟蹤常駐：訂閱關閉期間同樣維護基線（只跟蹤不推送、也不補推），重新開啟
  //   後按當前狀態繼續；未拿到基線前不判定"佇列為空"，避免把沒有資料當成佇列空；
  // - 只有配置持久化（MST_SUBSCRIBE_config），id 基線、計時器、傳送佇列全部只存記憶體。

  // 進度推送的檢查節拍：輕量 setTimeout 鏈，不引入高頻常駐輪詢。
  const PROGRESS_TICK_MS = 15000;
  // 完成通知中展示的佇列條目數。
  const QUEUE_PREVIEW_COUNT = 3;
  const RETRY_DELAYS_MS = [
    60000, 120000, 240000
  ];

  // 各渠道官方限流預設值（條/分鐘）：切換渠道時作為分鐘推送上限的預設值帶出。
  const CHANNEL_PER_MINUTE_DEFAULTS = {dingtalk: 20, wecom: 20, feishu: 100};
  // 佇列為空提醒的固定推送週期：每分鐘一條。
  const EMPTY_REMIND_INTERVAL_MS = 60000;
  // 會話靜默判定：線上時遊戲每 10 分鐘發一次 ping、服務端回 pong（遊戲原始碼
  // `this.pingInterval = setInterval(this.sendPing, 6e5)`，pong 不在 MST 忽略的訊息型別裡），
  // 因此「超過 11 分鐘沒收到任何遊戲訊息」只可能是會話已死而 close 事件沒被觀測到
  // （半開連線、頁面橋異常等）。此時按掉線處理，不再用陳舊佇列定時推送。
  const SESSION_SILENT_MS = 11 * 60 * 1000;

  function createDefaultConfig() {
    return {
      enabled: false,
      channel: 'dingtalk',
      // 最小推送間隔取渠道限速允許的下限：釘釘/企微約 20 條每分鐘，5 秒一條仍在限流之內。
      minIntervalSec: 5,
      progressIntervalMin: 30,
      pushPerMinute: CHANNEL_PER_MINUTE_DEFAULTS.dingtalk,
      // 訊息型別開關：預設全勾。
      notifyComplete: true,
      notifyStart: true,
      notifyProgress: true,
      notifyEmpty: true,
      dingtalk: {url: '', secret: ''},
      wecom: {key: ''},
      feishu: {url: '', secret: ''}
    };
  }

  function clampInt(value, min, max, fallback) {
    const parsed = Number.parseInt(value, 10);
    if (!Number.isFinite(parsed)) return fallback;
    return Math.min(max, Math.max(min, parsed));
  }

  class SubscribeNotificationFeature {
    // 各渠道官方配置說明連結（設定彈窗渠道配置區內展示）。
    static CHANNEL_DOCS = {
      dingtalk: 'https://open.dingtalk.com/document/robots/custom-robot-access',
      wecom: 'https://developer.work.weixin.qq.com/document/path/99110',
      feishu: 'https://open.feishu.cn/document/client-docs/bot-v3/add-custom-bot'
    };

    // 渠道預設分鐘推送上限（與官方限流一致：釘釘/企微約 20 條每分鐘、飛書 100 條每分鐘）。
    static get CHANNEL_PER_MINUTE_DEFAULTS() {
      return CHANNEL_PER_MINUTE_DEFAULTS;
    }

    constructor(ctx) {
      this.ctx = ctx;
      this.inited = false;
      this.config = null;
      this.tracker = new QueueChangeTracker();
      this.sender = null;
      this.hmac = null;
      this.progressTimer = null;
      this.lastProgressAt = 0;
      this.lastEmptyRemindAt = 0;
      this.partyReady = false;
      // 隊伍是否處於開戰狀態（partyInfo.party.status === 'battling'），進入時播報組隊戰鬥開始。
      this.partyBattling = false;
      // 是否拿到過隊伍狀態欄位：拿不到時組隊行動退回"隊首變化"播報，不至於一條開始通知都沒有。
      this.partyStatusKnown = false;
      // 最近一次收到遊戲訊息的時間：長時間靜默按掉線處理（見 SESSION_SILENT_MS）。
      this.lastMessageAt = 0;
      // 遊戲會話狀態：預設視為未確認線上，收到 WS open 或 init_character_data 才算確認。
      // 未確認前不跑定時推送——沒有資料不等於佇列是空的（頁面在未登入或斷線狀態開啟時
      // 從未收到基線，若按空佇列處理會每分鐘誤推一條提醒）。
      this.wsConnected = false;
      this.characterName = '';
      this.characterId = null;
      this.lastResult = null;
      this.settingsRoot = null;
    }

    init() {
      const {CONFIG} = this.ctx;
      if (!CONFIG.isGameSite || this.inited) return;
      this.inited = true;
      // 設定彈窗樣式為模組私有 CSS，注入一次即可。
      StyleService.ensure('mst-subscribe-notification-style', MST_SUBSCRIBE_CSS);
      this.config = this.readConfig();
      // 監聽與節拍常駐但代價極低，處理器內部按 isFeatureActive 過濾，
      // 訂閱開關變化後無需過載頁面即可生效。
      window.addEventListener('mst:ws:init-character-data', (event) => this.onInitCharacterData(event.detail));
      window.addEventListener('mst:ws:message', (event) => this.onWsMessage(event.detail));
      window.addEventListener('mst:ws:state', (event) => this.onWsState(event.detail));
      // 設定彈窗開啟時切換語言：重繪標題、幫助提示與設定表單（配置即時回寫，重繪無狀態丟失）。
      this.ctx.LanguageEvents?.subscribe(() => this.refreshLanguage());
      this.startProgressLoop();
    }

    // 功能啟用條件：遊戲站 + 訂閱總開關開啟。
    isFeatureActive() {
      const {CONFIG} = this.ctx;
      if (!CONFIG.isGameSite) return false;
      return Boolean(this.config?.enabled);
    }

    // ---- 配置（唯一持久化內容） ----

    // 配置按角色分使用者儲存：同一鍵下以 characterId 分桶，不同角色互不影響。
    // 頁內切換角色時 URL 引數可能不變，因此優先取 init_character_data 裡的實際角色 id，
    // URL 引數只作為基線到達前的兜底。
    getStorageCharacterId() {
      return String(this.characterId || this.ctx.CONFIG.characterId || 'default');
    }

    readCharacterStore(key) {
      const parsed = JSON.parse(localStorage.getItem(key) || 'null');
      if (parsed && typeof parsed === 'object' && parsed.characters && typeof parsed.characters === 'object') {
        return parsed.characters;
      }
      // 舊版單角色扁平結構：遷移到當前角色名下（配置只儲存在本機瀏覽器）。
      if (parsed && typeof parsed.enabled === 'boolean') {
        return {[this.getStorageCharacterId()]: parsed};
      }
      return {};
    }

    readConfig() {
      const key = this.ctx.STORAGE_KEYS?.SUBSCRIBE_NOTIFICATION || 'MST_SUBSCRIBE_config';
      try {
        const store = this.readCharacterStore(key);
        return this.normalizeConfig(store[this.getStorageCharacterId()]);
      } catch {
        return createDefaultConfig();
      }
    }

    normalizeConfig(raw) {
      const defaults = createDefaultConfig();
      const source = raw && typeof raw === 'object' ? raw : {};
      return {
        enabled: Boolean(source.enabled),
        channel: [
          'dingtalk', 'wecom', 'feishu'
        ].includes(source.channel) ? source.channel : defaults.channel,
        minIntervalSec: clampInt(source.minIntervalSec, 5, 600, defaults.minIntervalSec),
        progressIntervalMin: clampInt(source.progressIntervalMin, 0, 240, defaults.progressIntervalMin),
        pushPerMinute: clampInt(
          source.pushPerMinute,
          1,
          100,
          CHANNEL_PER_MINUTE_DEFAULTS[source.channel] || defaults.pushPerMinute
        ),
        // 未顯式關閉（含舊配置缺欄位）視為勾選。
        notifyComplete: source.notifyComplete !== false,
        notifyStart: source.notifyStart !== false,
        notifyProgress: source.notifyProgress !== false,
        notifyEmpty: source.notifyEmpty !== false,
        dingtalk: {
          url: String(source.dingtalk?.url || ''),
          secret: String(source.dingtalk?.secret || '')
        },
        wecom: {key: String(source.wecom?.key || '')},
        feishu: {
          url: String(source.feishu?.url || ''),
          secret: String(source.feishu?.secret || '')
        }
      };
    }

    saveConfig() {
      const key = this.ctx.STORAGE_KEYS?.SUBSCRIBE_NOTIFICATION || 'MST_SUBSCRIBE_config';
      try {
        const store = this.readCharacterStore(key);
        store[this.getStorageCharacterId()] = this.config;
        localStorage.setItem(key, JSON.stringify({characters: store}));
      } catch (error) {
        console.warn('[MST] 訂閱通知配置儲存失敗:', error);
      }
    }

    updateConfig(patch) {
      this.config = this.normalizeConfig({...this.config, ...patch});
      this.saveConfig();
      this.ensureSender();
    }

    updateChannelConfig(channel, patch) {
      this.config[channel] = {...this.config[channel], ...patch};
      this.saveConfig();
    }

    isChannelConfigured(channel = this.config.channel) {
      if (channel === 'dingtalk') return Boolean(this.config.dingtalk.url);
      if (channel === 'wecom') return Boolean(this.config.wecom.key);
      if (channel === 'feishu') return Boolean(this.config.feishu.url);
      return false;
    }

    // ---- 官方訊息接入 ----

    onInitCharacterData(data) {
      const actions = Array.isArray(data?.characterActions) ? data.characterActions : [];
      const nextCharacterId =
        data?.character?.id ?? data?.characterID ?? this.ctx.CONFIG.characterId ?? this.tracker.characterId ?? null;
      const characterChanged = nextCharacterId != null && String(nextCharacterId) !== String(this.characterId ?? '');
      this.characterId = nextCharacterId ?? this.characterId;
      this.characterName = data?.character?.name || this.ctx.DataHub?.characterData?.raw?.character?.name || '';
      // 能收到 init_character_data 說明當前頁面 WS 會話線上（重連成功同樣走這裡）。
      this.wsConnected = true;
      this.lastMessageAt = Date.now();
      // 基線重建不觸發推送；進度計時從基線建立時刻起算。
      this.tracker.setQueue(actions, this.characterId);
      // 同步本方組隊準備狀態與隊伍開戰狀態作為基線：基線建立時的已準備、正在開戰都不算新事件。
      this.partyReady = this.readOwnPartyReady(data?.partyInfo);
      this.partyBattling = this.readPartyStatus(data?.partyInfo) === 'battling';
      this.markTaskActivity();
      if (characterChanged) {
        // 配置按角色分桶：切角色後必須重讀當前角色配置並重置傳送佇列，
        // 否則會沿用上一個角色的渠道與憑據推送（記憶體態不落盤，重讀即切換）。
        this.config = this.readConfig();
        this.sender?.dispose();
        this.sender = null;
        this.lastResult = null;
      }
    }

    // 佇列跟蹤常駐：訂閱關閉期間照常合併官方增量，保證重新開啟時基線就是當前佇列。
    // 是否推送由 handleEvent 內部按訂閱開關判斷，跟蹤與推送分離。
    onWsMessage(message) {
      // 任何遊戲訊息都算一次會話存活證據（含每 10 分鐘一次的 pong），供靜默兜底判定。
      this.lastMessageAt = Date.now();
      const type = message?.type;
      if (type === 'actions_updated') {
        this.handleEvent(this.tracker.applyActionsUpdate(message.endCharacterActions));
      } else if (type === 'action_completed') {
        this.handleEvent(this.tracker.applyActionCompleted(message.endCharacterAction));
      } else if (type === 'party_updated') {
        this.handlePartyUpdated(message);
      }
    }

    // 會話監控：遊戲 WebSocket close（網路斷開或同賬號被其他登入擠掉）後，當前頁面
    // 不再收到任何佇列訊息，繼續定時推送只會發出陳舊資料（多開頁面時表現為同一
    // 任務收到兩條資料差異很大的進度通知）。斷連期間暫停進度與空佇列提醒，重連
    // （open / init_character_data 重建基線）後自動恢復。
    onWsState(detail) {
      this.wsConnected = detail?.state !== 'closed';
    }

    // 讀取本方角色在隊伍槽位中的準備狀態（partyInfo.partySlotMap 按 characterID 匹配）。
    readOwnPartyReady(partyInfo) {
      const slotMap = partyInfo?.partySlotMap;
      if (!slotMap || typeof slotMap !== 'object') return false;
      const ownId = String(this.characterId ?? '');
      if (!ownId) return false;
      const ownSlot = Object.values(slotMap).find((slot) => String(slot?.characterID ?? '') === ownId);
      return Boolean(ownSlot?.isReady);
    }

    // 讀取隊伍狀態（partyInfo.party.status），順帶記錄"隊伍狀態可用"。
    readPartyStatus(partyInfo) {
      const status = partyInfo?.party?.status;
      if (typeof status === 'string' && status) this.partyStatusKnown = true;
      return status || null;
    }

    // 組隊戰鬥行動在同一條 CharacterAction 上持續累加 currentCount，取消準備再重新準備
    // 不會更換 id、也沒有 actions_updated/action_completed，官方只在 party_updated 裡
    // 攜帶準備狀態與隊伍狀態（partyInfo.party.status：creating/recruiting/battling/disbanded，
    // 官方在狀態進入 battling 時自己也會發“隊伍開戰”通知）。這裡做兩件事：
    // 1) 本方角色從未準備變為已準備（取消準備後再準備、戰後再次準備）視為新的戰鬥會話：
    //    重置進度計數基線與進度計時，定期進度通知從重新準備起重新計數；
    // 2) 隊伍狀態進入 battling（準備就緒並過了等待期、戰鬥真正開始）時播報任務開始——
    //    組隊行動的隊首通常早在等待隊伍時就已就位，id 沒變，靠隊首變化那條規則識別不到。
    handlePartyUpdated(message) {
      const partyInfo = message?.partyInfo;
      const isReady = this.readOwnPartyReady(partyInfo);
      const wasReady = this.partyReady;
      this.partyReady = isReady;
      const isBattling = this.readPartyStatus(partyInfo) === 'battling';
      const wasBattling = this.partyBattling;
      this.partyBattling = isBattling;
      if (isReady && !wasReady) {
        const task = this.tracker.getCurrentTask();
        if (task && task.partyID !== 0) {
          this.tracker.resetProgressBaseline();
          this.markTaskActivity();
        }
      }
      // 組隊戰鬥每次開戰各播報一條（戰鬥結束會退出 battling，下一次準備就緒再進入）。
      if (isBattling && !wasBattling) this.notifyPartyBattleStart();
    }

    // 組隊戰鬥開始通知：只有開始行，與隊首變化觸發的通知共用同一套文案。
    notifyPartyBattleStart() {
      if (!this.isFeatureActive() || this.config?.notifyStart === false) return;
      const task = this.tracker.getCurrentTask();
      // 隊伍開戰時隊首應當是組隊/戰鬥行動（partyID 非 0），否則不是本次開戰對應的任務。
      if (!task || task.partyID === 0) return;
      this.submitText(this.buildQueueChangeText({newTask: task, isEmpty: false}, {complete: false, start: true}));
    }

    handleEvent(event) {
      if (!event) return;
      // 任務切換後重置進度計時，避免舊任務的計時週期汙染新任務。
      this.markTaskActivity();
      // 訂閱關閉期間只跟蹤不推送：重新開啟後從當前狀態繼續，不補推關閉期間的變動。
      if (!this.isFeatureActive()) return;
      // 訊息型別開關各自決定這一條訊息裡出現哪幾行（計時仍重置）。
      const complete = event.type === 'completed' && this.config?.notifyComplete !== false;
      // 組隊/戰鬥行動（partyID 非 0）的開始改由"真正開戰"播報，見 notifyPartyBattleStart——
      // 隊伍要先準備就緒並過等待期，入隊即播報會在開戰前先發一條內容一樣的通知。
      const start =
        Boolean(event.newTask) && this.config?.notifyStart !== false && !this.isPartyStartDeferred(event.newTask);
      // 一次隊首變化只發一條訊息：完成行與開始行按各自開關決定是否出現在這一條裡。
      if (!complete && !start) return;
      this.submitText(this.buildQueueChangeText(event, {complete, start}));
    }

    // 組隊行動的開始是否交給開戰播報：僅當隊伍狀態可用（拿到過 partyInfo.party.status）時才移交，
    // 避免遊戲側不再提供隊伍狀態時組隊戰鬥一條開始通知都收不到。
    isPartyStartDeferred(task) {
      return task.partyID !== 0 && this.partyStatusKnown;
    }

    // ---- 定期進度推送 ----

    startProgressLoop() {
      if (this.progressTimer) return;
      const tick = () => {
        this.progressTimer = setTimeout(tick, PROGRESS_TICK_MS);
        try {
          this.checkProgress();
        } catch (error) {
          console.warn('[MST] 訂閱通知進度推送檢查失敗:', error);
        }
      };
      this.progressTimer = setTimeout(tick, PROGRESS_TICK_MS);
    }

    // 會話可信判定：定時推送（進度、空佇列）三條都滿足才跑，任一不滿足就按掉線處理，
    // 恢復（頁頭回來 / 重連基線重建）後自動繼續。
    // 1) 頁頭的角色資訊塊還在（右上角頭像所在塊）：遊戲判定掉線時會把整塊遊戲 UI 換成連線
    //    提示面板（遊戲原始碼 render 分支），頁頭隨之消失——取不到就說明當前不是正常遊戲介面；
    // 2) 沒有觀測到 WebSocket close：被擠掉/斷網時遊戲立刻斷開重連，事件比 UI 更早；
    // 3) 會話沒有長時間靜默：線上時遊戲每 10 分鐘發一次 ping、服務端回 pong（遊戲原始碼
    //    `setInterval(this.sendPing, 6e5)`），超過 11 分鐘收不到任何遊戲訊息說明連線已死但
    //    遊戲自己還沒察覺（半開連線），此時佇列資料已陳舊。
    isSessionTrustworthy(now = Date.now()) {
      if (!this.isHeaderPresent()) return false;
      if (this.wsConnected === false) return false;
      if (this.lastMessageAt && now - this.lastMessageAt > SESSION_SILENT_MS) return false;
      return true;
    }

    // 頁頭角色資訊塊是否還在：斷線時遊戲把整塊 UI 換成連線提示面板，頁頭與頭像都不再渲染。
    isHeaderPresent() {
      return Boolean(this.ctx.GameUiAdapter?.query('headerCharacterInfo'));
    }

    checkProgress() {
      if (!this.isFeatureActive()) return;
      const now = Date.now();
      // 掉線（被擠掉、斷網、靜默死連線、斷線後開啟的頁面）：暫停定時推送。
      if (!this.isSessionTrustworthy(now)) return;
      const task = this.tracker.getCurrentTask();
      if (!task) {
        // 未拿到過全量基線（未登入 / 頁面在斷線狀態開啟）：沒有資料不等於佇列為空，不推送。
        if (!this.tracker.hasBaseline) return;
        // 訊息型別開關：佇列為空提醒可單獨關閉；佇列空時固定每分鐘推送一條提醒。
        if (this.config?.notifyEmpty === false) return;
        if (now - this.lastEmptyRemindAt < EMPTY_REMIND_INTERVAL_MS) return;
        this.lastEmptyRemindAt = now;
        this.submitText(this.buildEmptyText());
        return;
      }
      // 有任務期間持續重新整理，保證佇列騰空後從下一分鐘起開始提醒。
      this.lastEmptyRemindAt = now;
      // 訊息型別開關：定期進度通知可單獨關閉。
      if (this.config?.notifyProgress === false) return;
      const intervalMin = Number(this.config.progressIntervalMin) || 0;
      if (intervalMin <= 0) return;
      if (now - this.lastProgressAt < intervalMin * 60000) return;
      this.lastProgressAt = now;
      this.submitText(this.buildProgressText(task));
    }

    markTaskActivity() {
      this.lastProgressAt = Date.now();
      this.lastEmptyRemindAt = Date.now();
    }

    // ---- 推送鏈路 ----

    ensureSender() {
      const minIntervalMs = Math.max(5, Number(this.config.minIntervalSec) || 5) * 1000;
      const perMinuteLimit = Math.max(1, Number(this.config.pushPerMinute) || 20);
      if (!this.sender) {
        this.sender = new NotificationSender({
          send: (text) => this.sendToChannel(text),
          minIntervalMs,
          perMinuteLimit,
          retryDelaysMs: RETRY_DELAYS_MS,
          onGiveUp: () => {
            this.lastResult = {time: new Date().toLocaleString(), ok: false, code: null, msg: 'retry exhausted'};
            this.refreshStatusLine();
          }
        });
      } else {
        this.sender.minIntervalMs = minIntervalMs;
        this.sender.perMinuteLimit = perMinuteLimit;
      }
      return this.sender;
    }

    submitText(text) {
      if (!this.isChannelConfigured()) return;
      this.ensureSender().submit(truncateForChannel(this.config.channel, text));
    }

    async sendToChannel(text) {
      const {GmApi, CONFIG} = this.ctx;
      const request = GmApi?.xmlHttpRequestApi?.();
      if (!request) throw new Error('GM request API unavailable');
      if (!CONFIG.isGameSite) throw new Error('invalid site');
      const channel = this.config.channel;
      this.hmac = this.hmac || createDefaultHmac();
      if (channel === 'dingtalk' && this.config.dingtalk.secret && !this.hmac) {
        throw new Error('WebCrypto unavailable');
      }
      let built;
      if (channel === 'dingtalk') {
        built = await buildDingTalkRequest(
          {url: this.config.dingtalk.url, secret: this.config.dingtalk.secret, content: text},
          {hmac: this.hmac}
        );
      } else if (channel === 'wecom') {
        built = buildWeComRequest({
          url: `https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=${encodeURIComponent(this.config.wecom.key)}`,
          content: text
        });
      } else {
        built = await buildFeishuRequest(
          {url: normalizeFeishuHookUrl(this.config.feishu.url), secret: this.config.feishu.secret, content: text},
          {hmac: this.hmac}
        );
      }
      const responseText = await new Promise((resolve, reject) => {
        request({
          method: 'POST',
          url: built.url,
          headers: built.headers,
          data: built.body,
          timeout: 15000,
          onload: (response) => resolve(response?.responseText || ''),
          onerror: () => reject(new Error('network error')),
          ontimeout: () => reject(new Error('timeout'))
        });
      });
      const result = parseChannelResponse(channel, responseText);
      this.lastResult = {time: new Date().toLocaleString(), ...result};
      this.refreshStatusLine();
      if (!result.ok) throw new Error(result.msg || `code ${result.code}`);
      return result;
    }

    // ---- 文案 ----

    buildHeader() {
      return `【MST】${this.ctx.i18n.t('subscribeNotificationMsgTitle')}`;
    }

    // 時間行帶完整日期：yyyy-MM-dd HH:mm:ss（不依賴本地化的 toLocaleString 輸出）。
    buildTimeLine() {
      const now = new Date();
      const pad = (value) => String(value).padStart(2, '0');
      return (
        `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ` +
        `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`
      );
    }

    // 角色名行：角色名優先；只有 id 時用「角色 <id>」區分同站多賬號；兩者都沒有說明
    // 還沒拿到角色資料，顯式標註而不是輸出沒有資訊量的佔位符（兩端都取不到時沒有基線、
    // 定時推送已被攔截，正常推送中不會出現，只剩手動測試傳送會遇到）。
    buildRoleLine() {
      const {i18n} = this.ctx;
      const owner =
        this.characterName ||
        (this.characterId
          ? i18n.t('subscribeNotificationRoleId', this.characterId)
          : i18n.t('subscribeNotificationRoleUnknown'));
      const suffix = this.ctx.CONFIG.isTestServer ? ` · ${i18n.t('subscribeNotificationServerTest')}` : '';
      return `${owner}${suffix}`;
    }

    // 行動名按官方 getActionDisplayName 口徑組裝（遊戲原始碼 main.chunk.js）：
    // - 鍊金類（/action_functions/alchemy：點金、分解、轉化、解精煉）顯示「行動名: 物品名」；
    // - 強化（/action_functions/enhancing）顯示「物品名」；
    // - 兩者在物品強化等級 >= 1 時追加 " +<等級>"；其餘行動直接用行動名（採集/製作類的
    //   actionHrid 本身按物品命名，如 /actions/brewing/alchemy_tea，官方也是直接取行動名）。
    // 物品來自 CharacterAction.primaryItemHash，格式與官方 computeItemFromHash 一致：
    // characterId::itemLocationHrid::itemHrid::enhancementLevel。解析不到物品時退回行動名
    // （官方此時顯示 actionsUtil.itemNotAvailable，推送裡顯示行動名更有用）。
    actionName(task) {
      const hrid = task?.actionHrid;
      const name = this.ctx.DataHub?.getLocalizedGameName('actionNames', hrid) || String(hrid || '');
      const actionFunction = this.ctx.DataHub?.getClientDataMap?.('actionDetailMap')?.[hrid]?.function;
      if (actionFunction !== '/action_functions/alchemy' && actionFunction !== '/action_functions/enhancing') {
        return name;
      }
      const item = this.primaryItem(task);
      if (!item) return name;
      const itemName = this.ctx.DataHub?.getLocalizedGameName('itemNames', item.itemHrid) || item.itemHrid;
      const enhanceSuffix = item.enhancementLevel >= 1 ? ` +${item.enhancementLevel}` : '';
      return actionFunction === '/action_functions/alchemy'
        ? `${name}: ${itemName}${enhanceSuffix}`
        : `${itemName}${enhanceSuffix}`;
    }

    // 解析 primaryItemHash（與官方 computeItemFromHash 同口徑，不做額外校驗）。
    primaryItem(task) {
      const parts = String(task?.primaryItemHash || '').split('::');
      const itemHrid = parts[2];
      if (!itemHrid) return null;
      return {itemHrid, enhancementLevel: Number.parseInt(parts[3], 10) || 0};
    }

    describeTask(task) {
      const {i18n} = this.ctx;
      if (!task) return '-';
      // 難度字尾與官方行動標題口徑一致：difficultyTier >= 1 時追加 " (T<tier>)"。
      const tierSuffix = task.difficultyTier >= 1 ? ` (T${task.difficultyTier})` : '';
      const name = this.actionName(task) + tierSuffix;
      if (task.hasMaxCount) {
        return i18n.t('subscribeNotificationTaskWithCount', name, task.currentCount ?? 0, task.maxCount ?? 0);
      }
      return i18n.t('subscribeNotificationTaskUnlimited', name);
    }

    // 隊首變化通知：標題行 + 完成行（可關）+ 開始行（可關）+ 等待佇列概覽 + 騰空提醒 +
    // 時間行 + 角色名行。上個任務結束與下個任務開始發生在同一次切換裡，兩者同屬這一條訊息。
    // 佇列概覽不含隊首、最多 3 項、超出以 …共 N 項 收尾；每項帶已完成/總次數。
    buildQueueChangeText(event, {complete = false, start = false} = {}) {
      const {i18n} = this.ctx;
      const lines = [
        this.buildHeader()
      ];
      if (complete && event.completedTask) {
        lines.push(`✅ ${i18n.t('subscribeNotificationTaskCompleted')}：${this.describeTask(event.completedTask)}`);
      }
      if (start && event.newTask) {
        lines.push(`▶️ ${i18n.t('subscribeNotificationTaskStarted')}：${this.describeTask(event.newTask)}`);
      }
      const preview = this.tracker.getWaitingQueuePreview(QUEUE_PREVIEW_COUNT);
      if (preview.length) {
        lines.push(i18n.t('subscribeNotificationQueueLabel'));
        preview.forEach((task, index) => lines.push(`${index + 1}. ${this.describeTask(task)}`));
        const total = this.tracker.getWaitingQueueLength();
        if (total > preview.length) lines.push(i18n.t('subscribeNotificationQueueMore', total));
      }
      if (event.isEmpty) lines.push(`⚠️ ${i18n.t('subscribeNotificationQueueEmpty')}`);
      lines.push(this.buildTimeLine(), this.buildRoleLine());
      return lines.join('\n');
    }

    // 進度通知與完成通知同構：標題行 + 進度行 + 等待佇列 + 時間行 + 角色名行。
    // 已完成次數走 tracker.getProgressCount：組隊戰鬥重新準備後按會話增量統計。
    buildProgressText(task) {
      const {i18n} = this.ctx;
      const name = this.actionName(task);
      const tierSuffix = task.difficultyTier >= 1 ? ` (T${task.difficultyTier})` : '';
      let progress = `⏳ ${i18n.t('subscribeNotificationProgressDone', name + tierSuffix, this.tracker.getProgressCount(task))}`;
      if (task.hasMaxCount) {
        const remaining = (task.maxCount ?? 0) - (task.currentCount ?? 0);
        if (remaining > 0) progress += i18n.t('subscribeNotificationProgressRemaining', remaining);
      }
      const lines = [
        this.buildHeader(), progress
      ];
      const preview = this.tracker.getWaitingQueuePreview(QUEUE_PREVIEW_COUNT);
      if (preview.length) {
        lines.push(i18n.t('subscribeNotificationQueueLabel'));
        preview.forEach((item, index) => lines.push(`${index + 1}. ${this.describeTask(item)}`));
        const total = this.tracker.getWaitingQueueLength();
        if (total > preview.length) lines.push(i18n.t('subscribeNotificationQueueMore', total));
      }
      lines.push(this.buildTimeLine(), this.buildRoleLine());
      return lines.join('\n');
    }

    // 佇列為空提醒：與完成通知同構，騰空後固定每分鐘推送一條。
    buildEmptyText() {
      const {i18n} = this.ctx;
      return [
        this.buildHeader(), `⚠️ ${i18n.t('subscribeNotificationQueueEmpty')}`, this.buildTimeLine(), this.buildRoleLine()
      ].join('\n');
    }

    buildTestText() {
      const {i18n} = this.ctx;
      return [
        this.buildHeader(), i18n.t('subscribeNotificationTestBody'), this.buildTimeLine(), this.buildRoleLine()
      ].join('\n');
    }

    // ---- 設定介面（工具箱選單入口） ----

    // 啟用開關切換：儲存配置後直接切換 DOM 顯隱（與渲染後的 applyEnabledVisibility 同源）。
    // 重新開啟時重置進度與空佇列計時：佇列跟蹤常駐，基線不會陳舊，但關閉期間的計時
    // 已凍結，不重置會讓開啟後的第一次檢查按關閉前的舊計時立刻推送。
    toggleEnabled(enabled) {
      this.updateConfig({enabled});
      if (enabled) this.markTaskActivity();
      this.applyEnabledVisibility();
    }

    // 狀態行只在點選測試傳送（或真實推送有結果）後顯示，未操作時留空。
    refreshStatusLine() {
      const element = document.getElementById('mst-subscribe-status');
      if (!element) return;
      element.textContent = this.lastResult
        ? `${this.lastResult.time} ${this.lastResult.ok ? '✅' : '❌'} ${this.lastResult.code ?? ''} ${this.lastResult.msg || ''}`.trim()
        : '';
    }

    openSettings() {
      const {Notifier, TemplateRenderer, i18n} = this.ctx;
      this.config = this.readConfig();
      return Notifier.html({
        title: i18n.t('subscribeNotificationTitle'),
        width: 'min(34rem, calc(100vw - 1rem))',
        popupClass: 'mst-subscribe-dialog',
        icon: 'action_queue',
        html: () => TemplateRenderer.html`<div id="mst-subscribe-settings-root"></div>`,
        didOpen: (popup) => {
          this.settingsRoot =
            popup?.querySelector('#mst-subscribe-settings-root') ||
            document.getElementById('mst-subscribe-settings-root');
          this.renderSettings();
          // 標題後的提示圖示與技能升級等彈窗一致：掛在 swal 標題上，說明內容為原提示行文案。
          this.helpController?.cleanup();
          this.helpController = this.ctx.CalculatorHelpPopover?.mount({
            popup,
            moduleName: 'subscribe',
            title: i18n.t('subscribeNotificationTitle'),
            heading: i18n.t('subscribeNotificationTitle'),
            content: i18n.t('subscribeNotificationHint')
          });
        },
        willClose: () => {
          this.helpController?.cleanup();
          this.helpController = null;
          this.settingsRoot = null;
        }
      });
    }

    // 整體重渲染設定區：渠道切換後欄位只展示當前渠道的配置項與文件連結。
    renderSettings() {
      const {TemplateRenderer} = this.ctx;
      if (!this.settingsRoot) return;
      TemplateRenderer.render(() => this.settingsTemplate(), this.settingsRoot);
      this.applyEnabledVisibility();
      this.refreshStatusLine();
    }

    // 語言切換時同步彈窗文案：標題、幫助提示與設定表單整體重繪。
    refreshLanguage() {
      const {i18n, CalculatorHelpPopover} = this.ctx;
      if (!this.settingsRoot?.isConnected) return;
      const popup = this.settingsRoot.closest('.mst-subscribe-dialog');
      const title = popup?.querySelector('.swal2-title');
      if (title) title.textContent = i18n.t('subscribeNotificationTitle');
      this.helpController?.cleanup();
      this.helpController =
        CalculatorHelpPopover?.mount({
          popup,
          moduleName: 'subscribe',
          title: i18n.t('subscribeNotificationTitle'),
          heading: i18n.t('subscribeNotificationTitle'),
          content: i18n.t('subscribeNotificationHint')
        }) || null;
      this.renderSettings();
    }

    // 啟用狀態決定後續選項的顯隱。uhtml 對 hidden 布林屬性的初始/增量繫結都不可靠，
    // 統一在渲染後直接寫 DOM，與 toggleEnabled 的切換行為保持同一來源。
    applyEnabledVisibility() {
      const root = this.settingsRoot || document.getElementById('mst-subscribe-settings-root');
      if (!root) return;
      const enabled = Boolean(this.config?.enabled);
      const detail = root.querySelector('.mst-subscribe-detail');
      if (detail) detail.hidden = !enabled;
    }

    settingsTemplate() {
      const {TemplateRenderer, i18n, utils} = this.ctx;
      const config = this.config;
      const gameButtonClass = utils.getGameButtonClass();
      const channel = config.channel;
      const field = (labelKey, inputTemplate) => TemplateRenderer.html`
    <label class="mst-subscribe-field">
      <span>${i18n.t(labelKey)}</span>
      ${inputTemplate}
    </label>`;
      const channelFields =
        channel === 'dingtalk'
          ? [
              field(
                'subscribeNotificationDingtalkUrl',
                TemplateRenderer.html`<input
            type="text"
            id="mst-subscribe-dingtalk-url"
            .value=${config.dingtalk.url}
            placeholder="https://oapi.dingtalk.com/robot/send?access_token=..."
            @input=${(event) => this.updateChannelConfig('dingtalk', {url: event.target.value.trim()})}
          />`
              ), field(
                'subscribeNotificationDingtalkSecret',
                TemplateRenderer.html`<input
            type="password"
            id="mst-subscribe-dingtalk-secret"
            .value=${config.dingtalk.secret}
            autocomplete="off"
            @input=${(event) => this.updateChannelConfig('dingtalk', {secret: event.target.value.trim()})}
          />`
              )
            ]
          : channel === 'wecom'
            ? [
                field(
                  'subscribeNotificationWeComKey',
                  TemplateRenderer.html`<input
              type="password"
              id="mst-subscribe-wecom-key"
              .value=${config.wecom.key}
              autocomplete="off"
              @input=${(event) => this.updateChannelConfig('wecom', {key: event.target.value.trim()})}
            />`
                )
              ]
            : [
                field(
                  'subscribeNotificationFeishuUrl',
                  TemplateRenderer.html`<input
              type="text"
              id="mst-subscribe-feishu-url"
              .value=${config.feishu.url}
              placeholder="完整 Hook 地址或僅填 hook-id"
              @input=${(event) => this.updateChannelConfig('feishu', {url: event.target.value.trim()})}
            />`
                ), field(
                  'subscribeNotificationFeishuSecret',
                  TemplateRenderer.html`<input
              type="password"
              id="mst-subscribe-feishu-secret"
              .value=${config.feishu.secret}
              autocomplete="off"
              @input=${(event) => this.updateChannelConfig('feishu', {secret: event.target.value.trim()})}
            />`
                )
              ];
      return TemplateRenderer.html`
  <div class="mst-subscribe-form">
    <div class="mst-subscribe-section-title">${i18n.t('subscribeNotificationSectionGeneral')}</div>
    <label class="mst-subscribe-checkbox">
      <input
        type="checkbox"
        id="mst-subscribe-enabled"
        .checked=${config.enabled}
        @change=${(event) => this.toggleEnabled(event.target.checked)}
      />
      <span>${i18n.t('subscribeNotificationEnabled')}</span>
    </label>
    <div class="mst-subscribe-detail">
      <div class="mst-subscribe-row">
        <label class="mst-subscribe-field">
          <span>${i18n.t('subscribeNotificationMinInterval')}</span>
          <input
            type="number"
            id="mst-subscribe-min-interval"
            min="5"
            max="600"
            step="1"
            .value=${config.minIntervalSec}
            @change=${(event) => this.updateConfig({minIntervalSec: event.target.value})}
          />
        </label>
        <label class="mst-subscribe-field">
          <span>${i18n.t('subscribeNotificationProgressInterval')}</span>
          <input
            type="number"
            id="mst-subscribe-progress-interval"
            min="0"
            max="240"
            step="1"
            .value=${config.progressIntervalMin}
            @change=${(event) => this.updateConfig({progressIntervalMin: event.target.value})}
          />
        </label>
      </div>
      <div class="mst-subscribe-section-title">${i18n.t('subscribeNotificationMsgType')}</div>
      <div class="mst-subscribe-type-row">
        <span class="mst-subscribe-type-label">${i18n.t('subscribeNotificationTypeQueue')}</span>
        <label
          class="mst-subscribe-type-checkbox"
          title=${i18n.t('subscribeNotificationTypeStartTitle')}
        >
          <input
            type="checkbox"
            id="mst-subscribe-type-start"
            .checked=${config.notifyStart}
            @change=${(event) => this.updateConfig({notifyStart: event.target.checked})}
          />
          <span>${i18n.t('subscribeNotificationTypeStart')}</span>
        </label>
        <label
          class="mst-subscribe-type-checkbox"
          title=${i18n.t('subscribeNotificationTypeCompleteTitle')}
        >
          <input
            type="checkbox"
            id="mst-subscribe-type-complete"
            .checked=${config.notifyComplete}
            @change=${(event) => this.updateConfig({notifyComplete: event.target.checked})}
          />
          <span>${i18n.t('subscribeNotificationTypeComplete')}</span>
        </label>
        <label
          class="mst-subscribe-type-checkbox"
          title=${i18n.t('subscribeNotificationTypeEmptyTitle')}
        >
          <input
            type="checkbox"
            id="mst-subscribe-type-empty"
            .checked=${config.notifyEmpty}
            @change=${(event) => this.updateConfig({notifyEmpty: event.target.checked})}
          />
          <span>${i18n.t('subscribeNotificationTypeEmpty')}</span>
        </label>
        <label
          class="mst-subscribe-type-checkbox"
          title=${i18n.t('subscribeNotificationTypeProgressTitle')}
        >
          <input
            type="checkbox"
            id="mst-subscribe-type-progress"
            .checked=${config.notifyProgress}
            @change=${(event) => this.updateConfig({notifyProgress: event.target.checked})}
          />
          <span>${i18n.t('subscribeNotificationTypeProgress')}</span>
        </label>
        </div>
      <div class="mst-subscribe-section-title">${i18n.t('subscribeNotificationSectionChannel')}</div>
      <div class="mst-subscribe-row">
        <label class="mst-subscribe-field">
          <span>
            ${i18n.t('subscribeNotificationChannel')}
            <a
              class="mst-subscribe-doc-link"
              href=${SubscribeNotificationFeature.CHANNEL_DOCS[channel]}
              target="_blank"
              rel="noreferrer"
            >${i18n.t('subscribeNotificationDocLink')}</a>
          </span>
          <select
            id="mst-subscribe-channel"
            .value=${channel}
            @change=${(event) => {
              // 切換渠道時按官方限流帶出該渠道預設的分鐘推送上限，使用者可再修改。
              const nextChannel = event.target.value;
              this.updateConfig({
                channel: nextChannel,
                pushPerMinute: SubscribeNotificationFeature.CHANNEL_PER_MINUTE_DEFAULTS[nextChannel]
              });
              this.renderSettings();
            }}
          >
            <option value="dingtalk">${i18n.t('subscribeNotificationChannelDingtalk')}</option>
            <option value="wecom">${i18n.t('subscribeNotificationChannelWeCom')}</option>
            <option value="feishu">${i18n.t('subscribeNotificationChannelFeishu')}</option>
          </select>
        </label>
        <label class="mst-subscribe-field">
          <span>${i18n.t('subscribeNotificationPushLimit')}</span>
          <input
            type="number"
            id="mst-subscribe-push-limit"
            min="1"
            max="100"
            step="1"
            .value=${config.pushPerMinute}
            @change=${(event) => this.updateConfig({pushPerMinute: event.target.value})}
          />
        </label>
      </div>
      <div class="mst-subscribe-row">${channelFields}</div>
      <div class="mst-subscribe-actions">
        <button type="button" id="mst-subscribe-test" class=${gameButtonClass} @click=${() => this.sendTestMessage()}>
          ${i18n.t('subscribeNotificationTestSend')}
        </button>
        <span class="mst-subscribe-status" id="mst-subscribe-status"></span>
      </div>
    </div>
  </div>`;
    }

    async sendTestMessage() {
      const {Notifier, i18n} = this.ctx;
      if (!this.isChannelConfigured()) {
        Notifier.toast(i18n.t('subscribeNotificationInvalid'), 'warning');
        return;
      }
      try {
        await this.sendToChannel(this.buildTestText());
        Notifier.toast(i18n.t('subscribeNotificationTestOk'), 'success');
      } catch (error) {
        Notifier.toast(`${i18n.t('subscribeNotificationTestFail')}：${error.message}`, 'error');
      }
    }

    dispose() {
      if (this.progressTimer) clearTimeout(this.progressTimer);
      this.progressTimer = null;
      this.sender?.dispose();
      this.sender = null;
    }
  }

  // toolkit-menu-feature
  class ToolkitMenuFeature {
    constructor(
      ctx,
      {
        characterCardFeature,
        appController,
        combatCalculator,
        abilityCalculator,
        equipmentComparison,
        dungeonCalculator,
        subscribeNotification
      }
    ) {
      this.ctx = ctx;
      this.characterCardFeature = characterCardFeature;
      this.appController = appController;
      this.combatCalculator = combatCalculator;
      this.abilityCalculator = abilityCalculator;
      this.equipmentComparison = equipmentComparison;
      this.dungeonCalculator = dungeonCalculator;
      this.subscribeNotification = subscribeNotification;
      this.dropdownCleanup = null;
      this.outsideClickHandler = (event) => {
        const dropdown = document.getElementById('mst-toolkit-character-dropdown');
        if (dropdown && !dropdown.contains(event.target)) this.closeDropdown();
      };
      this.openHandler = (event) =>
        this.toggleDropdown(event?.detail?.trigger || null, event?.detail?.anchorRect || null);
    }

    getActions() {
      const {GameNavigationService, Notifier, i18n} = this.ctx;
      // 選單順序按常用工作流排列：資料與升級工具在前，站點導航放最後。
      return [
        {key: 'userCharacterCard', icon: 'social', handler: () => this.characterCardFeature.showMyCharacterCard()}, {
          key: 'subscribeNotification',
          icon: 'action_queue',
          handler: () => this.subscribeNotification.openSettings()
        }, {
          key: 'abilityUpgradeCalculator',
          icon: 'skills',
          handler: () => this.abilityCalculator.open()
        }, {key: 'houseUpgradeCalculator', icon: 'house', handler: () => this.appController.openCalculator()}, {
          key: 'combatUpgradeCalculator',
          icon: 'experience',
          handler: () => this.combatCalculator.open()
        },
        {
          key: 'equipmentComparison',
          icon: 'loadout',
          handler: () => this.equipmentComparison.open()
        }, {key: 'dungeonProfitCalculator', icon: 'loot_tracker', handler: () => this.dungeonCalculator.open()}, {
          key: 'combatSimAiwwb',
          icon: 'combat',
          handler: () => this.openCombatSimulator()
        }, {
          key: 'switchCharacter',
          icon: 'switch_character',
          handler: () => {
            if (!GameNavigationService.switchCharacter()) Notifier.toast(i18n.t('navigationUnavailable'), 'warning');
          }
        }
      ];
    }

    // 跳轉 aiwwb 戰鬥模擬器；window.open 傳固定 target 名，重複點選複用同一視窗不新開。
    openCombatSimulator() {
      window.open('https://aiwwb.github.io/milkywayidle_battle/dist/', 'mst-combat-sim-aiwwb');
    }

    refresh() {
      const {i18n} = this.ctx;
      document.querySelectorAll('.mst-my-character-card-btn').forEach((button) => {
        const text = i18n.t('toolkitShort');
        const title = i18n.t('toolkitTitle');
        if (button.textContent !== text) button.textContent = text;
        if (button.getAttribute('title') !== title) button.setAttribute('title', title);
      });
    }

    toggleDropdown(trigger, anchorRect) {
      const {GameUiAdapter} = this.ctx;
      const old = document.getElementById('mst-toolkit-character-dropdown');
      if (old) {
        this.closeDropdown();
        return;
      }
      // 優先錨定到點選來源附近：從頭像彈出層開啟時用點選前捕獲的彈出層矩形（彈出層隨後被關閉並解除安裝，
      // 脫離文件的元素無法再讀取位置），下拉右上角與彈出層右上角對齊；頁頭入口保持錨定按鈕自身；
      // 找不到來源時回退到遊戲頭部角色資訊區域。
      const avatarMenu = anchorRect ? null : trigger?.closest?.('[class*="Header_avatarMenu"]');
      const host =
        avatarMenu || trigger?.closest?.('[class*="Header_characterInfo"]') || GameUiAdapter.query('headerCharacterInfo');
      if (!host && !anchorRect) return;
      const dropdown = document.createElement('div');
      dropdown.id = 'mst-toolkit-character-dropdown';
      this.renderDropdown(dropdown);
      document.body.appendChild(dropdown);
      // 從頭像彈出層開啟時下拉佔據彈出層原位（右緣與頂部對齊整塊浮層），頁頭入口保持錨定按鈕自身。
      const positionAnchor = anchorRect ? {getBoundingClientRect: () => anchorRect} : avatarMenu || trigger || host;
      this.bindDropdownPosition(dropdown, positionAnchor, Boolean(anchorRect || avatarMenu));
      setTimeout(() => document.addEventListener('click', this.outsideClickHandler), 0);
    }

    closeDropdown() {
      document.removeEventListener('click', this.outsideClickHandler);
      this.dropdownCleanup?.();
      this.dropdownCleanup = null;
      document.getElementById('mst-toolkit-character-dropdown')?.remove();
    }

    // alignTop = true 時下拉頂部與錨點頂部對齊（頭像浮窗場景：浮窗關閉後下拉停在原位置），
    // 空間不足時仍在視口內收斂；預設沿錨點下方展開。
    bindDropdownPosition(dropdown, trigger, alignTop = false) {
      const positionDropdown = () => {
        if (!dropdown.isConnected) return;
        const viewport = window.visualViewport;
        const viewportLeft = viewport?.offsetLeft || 0;
        const viewportTop = viewport?.offsetTop || 0;
        const viewportWidth = viewport?.width || document.documentElement.clientWidth || window.innerWidth;
        const viewportHeight = viewport?.height || document.documentElement.clientHeight || window.innerHeight;
        const viewportRight = viewportLeft + viewportWidth;
        const viewportBottom = viewportTop + viewportHeight;
        const margin = 8;
        const gap = 6;
        const triggerRect = trigger?.getBoundingClientRect?.() || {
          right: viewportRight - margin,
          top: viewportTop + margin,
          bottom: viewportTop + margin
        };
        dropdown.style.maxHeight = Math.max(8 * 16, viewportHeight - margin * 2) + 'px';
        const dropdownRect = dropdown.getBoundingClientRect();
        const preferredLeft = triggerRect.right - dropdownRect.width;
        const left = Math.max(
          viewportLeft + margin,
          Math.min(preferredLeft, viewportRight - dropdownRect.width - margin)
        );
        const belowTop = triggerRect.bottom + gap;
        const aboveTop = triggerRect.top - dropdownRect.height - gap;
        const top = alignTop
          ? Math.max(viewportTop + margin, Math.min(triggerRect.top, viewportBottom - dropdownRect.height - margin))
          : belowTop + dropdownRect.height <= viewportBottom - margin
            ? belowTop
            : Math.max(viewportTop + margin, Math.min(aboveTop, viewportBottom - dropdownRect.height - margin));
        dropdown.style.left = `${left}px`;
        dropdown.style.top = `${top}px`;
        dropdown.style.right = 'auto';
      };
      window.addEventListener('resize', positionDropdown);
      window.visualViewport?.addEventListener('resize', positionDropdown);
      window.visualViewport?.addEventListener('scroll', positionDropdown);
      this.dropdownCleanup = () => {
        window.removeEventListener('resize', positionDropdown);
        window.visualViewport?.removeEventListener('resize', positionDropdown);
        window.visualViewport?.removeEventListener('scroll', positionDropdown);
      };
      if (window.requestAnimationFrame) window.requestAnimationFrame(positionDropdown);
      else setTimeout(positionDropdown, 0);
    }

    renderDropdown(dropdown) {
      const {TemplateRenderer, i18n, utils} = this.ctx;
      if (!dropdown) return;
      const miscSprite = utils.getSpriteUrl('misc') || '/static/media/misc_sprite.cfad291b.svg';
      TemplateRenderer.render(
        () => TemplateRenderer.html`
  <div class="mst-toolkit-dropdown-title">${i18n.t('toolkitTitle')}</div>
  ${this.getActions().map(
    ({key, icon, handler}) => TemplateRenderer.html`
  <button type="button" class="mst-toolkit-action" @click=${() => {
    dropdown.remove();
    handler();
  }}>
    <svg aria-hidden="true"><use href=${miscSprite + '#' + icon}></use></svg>
    <span>${i18n.t(key)}</span>
  </button>`
  )}
`,
        dropdown
      );
    }

    // 在右上角頭像彈出層（遊戲原生 Header_avatarMenu 選單）裡注入工具箱入口，
    // 放在所有條目最前面（標題行之下、檢視資料之前）；選單每次開啟都會重新掛載，由公共觀察器注入。
    addAvatarMenuEntry() {
      const {i18n} = this.ctx;
      const menu = document.querySelector('[class*="Header_avatarMenu"]');
      if (!menu) return;
      const label = i18n.t('toolkitTitle');
      const existingButton = menu.querySelector('.mst-avatar-toolkit-btn');
      if (existingButton) {
        if (existingButton.textContent !== label) existingButton.textContent = label;
        if (existingButton.getAttribute('title') !== label) existingButton.setAttribute('title', label);
        return;
      }
      const gameButtonClasses = [
        ...(menu.querySelector('button')?.classList || [])
      ].filter((className) => className.startsWith('Button_button__') || className.startsWith('Button_fullWidth__'));
      const button = document.createElement('button');
      button.type = 'button';
      button.className = [
        ...gameButtonClasses, 'mst-avatar-toolkit-btn'
      ]
        .filter(Boolean)
        .join(' ');
      button.textContent = label;
      button.title = label;
      button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        // 先捕獲彈出層當前位置（遊戲原生以 MUI Tooltip 渲染整塊浮層，placement bottom-end 錨定到頭像按鈕）；
        // 元件關閉後浮層會解除安裝，脫離文件後無法再讀取矩形。與遊戲自身浮層出現位置保持一致——
        // 下拉右上角對齊彈出層整體（含內邊距與邊框）的右上角，而不是對齊被內邊距包裹的內部選單。
        const menu = button.closest('[class*="Header_avatarMenu"]');
        const anchorRect =
          menu?.closest('.MuiTooltip-tooltip')?.getBoundingClientRect() || menu?.getBoundingClientRect() || null;
        document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true, cancelable: true}));
        window.dispatchEvent(new CustomEvent('mst:toolkit:open', {detail: {trigger: button, anchorRect}}));
      });
      const firstButton = menu.querySelector('button');
      if (firstButton) menu.insertBefore(button, firstButton);
      else menu.appendChild(button);
    }

    refresh() {
      const {i18n} = this.ctx;
      document.querySelectorAll('.mst-my-character-card-btn').forEach((button) => {
        const text = i18n.t('toolkitShort');
        const title = i18n.t('toolkitTitle');
        if (button.textContent !== text) button.textContent = text;
        if (button.getAttribute('title') !== title) button.setAttribute('title', title);
      });
      this.addAvatarMenuEntry();
    }

    init() {
      const {CONFIG, LanguageEvents, utils} = this.ctx;
      if (!CONFIG.isGameSite) return;
      // 入口按鈕由其它模組注入，這裡只監聽統一事件並維護下拉選單文案。
      window.addEventListener('mst:toolkit:open', this.openHandler);
      this.observer = utils.observeBody(() => this.refresh());
      LanguageEvents.subscribe(() => {
        this.refresh();
      });
    }
  }

  function installModules(ctx) {
    // 先完成靜態 configure，再把建構子掛到 ctx，避免模組之間直接迴圈 import。
    const OriginalCharacterCardFeature = createOriginalCharacterCardFeature(ctx);
    CharacterCardFeature.configure(ctx, OriginalCharacterCardFeature);
    CombatSimulatorConverter.configure(ctx);
    CombatSimImportFeature.configure(ctx);
    DungeonProfitCalculatorFeature.configure(ctx);
    EdsMilkonomyFeature.configure(ctx, CombatSimulatorConverter);
    EquipmentComparisonService.configure(ctx, CombatSimulationService);
    HouseCalculatorUI.configure(ctx, ctx.Notifier);
    HouseCalculatorLauncher.configure(ctx);
    LabyrinthSupplyFeature.configure(ctx);
    MarketplaceCartFeature.configure(ctx);

    ctx.AbilityUpgradeCalculatorFeature = AbilityUpgradeCalculatorFeature;
    ctx.BuildScoreService = BuildScoreService;
    ctx.CharacterCardFeature = CharacterCardFeature;
    ctx.CombatSimulationService = CombatSimulationService;
    ctx.CombatSimImportFeature = CombatSimImportFeature;
    ctx.CombatUpgradeCalculatorFeature = CombatUpgradeCalculatorFeature;
    ctx.CombatSimulatorConverter = CombatSimulatorConverter;
    ctx.DungeonProfitCalculatorFeature = DungeonProfitCalculatorFeature;
    ctx.DungeonProfitCalculatorService = DungeonProfitCalculatorService;
    ctx.EdsMilkonomyFeature = EdsMilkonomyFeature;
    ctx.EquipmentComparisonFeature = EquipmentComparisonFeature;
    ctx.EquipmentComparisonService = EquipmentComparisonService;
    ctx.HouseCalculator = HouseCalculator;
    ctx.HouseCalculatorUI = HouseCalculatorUI;
    ctx.LabyrinthSupplyFeature = LabyrinthSupplyFeature;
    ctx.MarketplaceCartFeature = MarketplaceCartFeature;
    ctx.SubscribeNotificationFeature = SubscribeNotificationFeature;
    ctx.ToolkitMenuFeature = ToolkitMenuFeature;
  }

